// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Sıralama ve arama algoritmaları uygulamalı (kolay).
const ozComputing7Kolay = <(String, String, List<String>, String)>[
  ('Doğrusal aramayla taranan bir listede \'başa taşı\' kuralının ortalama arama süresini kısaltmasının dayandığı gözlem hangisidir?', 'Yakın zamanda erişilen öğelere yeniden erişilme olasılığı yüksektir', ['Listedeki öğeler her erişimden sonra kendiliğinden tam olarak sıralanır', 'Başa alınan öğe bir daha hiç aranmaz', 'Listenin uzunluğu her erişimde azalır'], 'Erişimlerde yerellik (aynı öğelerin kısa aralıklarla tekrar istenmesi) varsa, sık istenen öğeler başa yakın durduğu için az karşılaştırmayla bulunur.'),
  ('Sayma (count) kuralıyla düzenlenen kendi kendini düzenleyen bir listede öğeler hangi ölçüte göre dizili tutulur?', 'Her öğeye bugüne dek kaç kez erişildiğine göre', ['Öğelerin listeye ilk kez eklendikleri tarih ve saate göre', 'Öğelerin alfabetik sırasına göre', 'Öğelerin bellekteki adreslerine göre'], 'Her öğe için bir erişim sayacı tutulur ve liste, sayaçları büyükten küçüğe olacak biçimde güncellenir; böylece en sık aranan öğeler başta kalır.'),
  ('Artan sırada dizili 2, 5, 9, 14, 20 listesinde 10 değeri doğrusal aramayla aranıyor. Algoritma aranan değerden büyük bir elemana rastlayınca durduğuna göre kaç elemanla karşılaştırma yapılır?', '4', ['3', '5', '10'], '2, 5 ve 9 değerleri 10\'dan küçüktür; 14\'e gelindiğinde 10\'un daha ileride olamayacağı anlaşılır. Toplam dört elemana bakılır.'),
  ('Sırasız bir dizide bir değerin kaç kez geçtiğini bulan doğrusal algoritma, değeri ilk bulduğu anda neden duramaz?', 'Aynı değer dizinin geri kalanında yine bulunabilir', ['Dizinin sonuna gözcü eklenmesi gerekir', 'İlk eşleşme çoğu zaman yanlış alarm olduğundan doğrulanması gerekir', 'Dizi önce sıralanmadan sayım yapılamaz'], 'Sayma işi her eşleşmeyi bulmayı gerektirir; bu yüzden dizi sonuna kadar taranır ve her zaman n karşılaştırma yapılır.'),
  ('Tek yönlü bağlı listede tutulan sıralı verilerde ikili arama neden pratikte kazanç sağlamaz?', 'Ortadaki düğüme ulaşmak için baştan itibaren yürümek gerekir', ['Bağlı listeler sıralı tutulamaz', 'Bağlı listedeki düğümler arasında karşılaştırma işlemi tanımlanamaz', 'İkili arama yalnız tam sayılarla çalışır'], 'Dizilerde indisle anında erişilen orta elemana bağlı listede ancak düğüm düğüm ilerleyerek varılır; bu yürüyüş toplamda doğrusal zaman alır.'),
  ('Bir programda adlar [Ece, Can, Ali] ve aynı sıradaki notlar [70, 85, 90] iki ayrı dizide tutuluyor. \'Can\' doğrusal aramayla bulunup bulunduğu indisteki not okunursa hangi değer elde edilir?', '85', ['70', '90', 'Bulunamaz'], 'Can adlar dizisinin ikinci elemanıdır; paralel dizilerde aynı indis aynı kişiye ait olduğundan notlar dizisinin ikinci elemanı olan 85 okunur.'),
  ('Sırasız bir sıcaklık listesinde 30 derecenin üzerindeki ilk günü bulmak gerekiyor. Bu iş için en uygun yöntem hangisidir?', 'Baştan başlayıp koşulu ilk sağlayan elemanda durmak', ['Listeyi sıralayıp ikili arama yapmak', 'Listeyi sondan başa tarayıp koşulu sağlayan son eşleşmeyi almak', 'Rastgele indisler seçip koşulu denemek'], '\'İlk gün\' sorusu orijinal sıraya bağlıdır; sıralama bu sırayı bozar. Baştan taranıp ilk uygun elemanda durulur.'),
  ('Sıralı bir dizide bir değerin son görüldüğü konumu bulmak için en verimli yol hangisidir?', 'Değerden kesin büyük ilk elemanın indisini ikili aramayla bulup bir çıkarmak', ['Diziyi baştan sona doğrusal olarak tarayıp her eşleşmeyi kaydetmek', 'İkili aramayla herhangi bir eşleşme bulup durmak', 'Diziyi ters çevirip yeniden sıralamak'], 'Üst sınır (upper bound) ikili aramayla O(log n) sürede bulunur; bir eksiği, değer dizide varsa son geçtiği konumdur.'),
  ('Python\'da bisect.bisect_right([1, 4, 6, 6, 9], 6) çağrısı hangi indisi döndürür?', '4', ['2', '3', '5'], 'bisect_right, eşit elemanların sağındaki ekleme yerini verir; iki 6\'dan sonra gelen 9\'un indisi olan 4 döner.'),
  ('Sıralı 3, 7, 12, 18, 25 dizisinde 15\'ten küçük olmayan en küçük eleman (tavan değeri) hangisidir?', '18', ['12', '25', '15'], '15 dizide yoktur; ondan büyük ya da eşit elemanların en küçüğü 18\'dir. Bu değer alt sınır aramasıyla bulunur.'),
  ('Bir vergi programında dilim başlangıçları sıralı olarak 0, 10 000, 30 000, 70 000 TL diye tutuluyor. 45 000 TL\'lik gelirin hangi dilime girdiğini bulmak için hangi arama işlemi kullanılır?', 'Gelire eşit ya da ondan küçük en büyük başlangıcı bulmak', ['Gelirden büyük en küçük başlangıcı bulmak', 'Gelire en yakın iki dilim başlangıcının aritmetik ortalamasını almak', 'Başlangıçların toplamını gelirle karşılaştırmak'], 'Gelir, başlangıcı kendisini aşmayan son dilime aittir; bu bir taban (floor) aramasıdır ve 45 000 için 30 000 dilimi bulunur.'),
  ('Kapalı aralıklı ikili arama boş bir dizi üzerinde çağrılıyor (alt = 0, üst = −1). Ne olur?', 'Döngüye hiç girilmeden \'bulunamadı\' döner', ['İlk karşılaştırmada dizi sınırı aşılır', 'Orta indis 0 olur ve bir eleman okunur', 'Döngü bir kez çalışır ve 0 numaralı indisteki elemanı döndürür'], 'Başlangıçta alt > üst olduğundan \'alt ≤ üst\' koşulu yanlıştır; hiçbir elemana erişilmeden arama başarısız sonuçlanır.'),
  ('Öğrenci kayıtları ada göre sıralı tutuluyor. Bir programcı bu dizide yaşı 17 olan öğrenciyi ikili aramayla bulmaya çalışıyor. Bu yaklaşımın sorunu nedir?', 'Dizi aranan anahtara göre sıralı değildir', ['İkili arama yalnız metinlerle çalışır', 'Yaş değerleri tam sayı olduğu için karşılaştırılamaz', 'Ada göre sıralı dizide hiç arama yapılamaz'], 'İkili arama, dizinin aramada kullanılan anahtara göre sıralı olmasını gerektirir. Ada göre sıralı dizide yaşlar karışıktır; ya doğrusal arama yapılmalı ya da yaşa göre sıralanmalıdır.'),
  ('Paket taşıma gibi \'en küçük yeterli kapasiteyi bul\' problemlerinde, cevabın ikili aramayla aranabilmesinin dayanağı nedir?', 'Bir kapasite yetiyorsa ondan büyük her kapasite de yeter', ['Paket ağırlıkları her zaman sıralı verilir', 'Kapasite değerleri yalnız asal sayılardan seçilebildiği için aralık seyrektir', 'Gün sayısı kapasiteyle doğru orantılıdır'], '\'Kapasite yeter mi?\' yüklemi YANLIŞ, …, YANLIŞ, DOĞRU, …, DOĞRU biçiminde monotondur; bu sayede ilk DOĞRU noktası ikili aramayla bulunur.'),
  ('Bir denklemin kökü [0, 1] aralığında ikiye bölme yöntemiyle aranıyor. Her adımda aralık yarıya indiğine göre 10 adımdan sonra aralığın genişliği kaçtır?', '1/1024', ['1/512', '1/100', '1/10'], 'Her adımda genişlik ikiye bölünür: 1/2¹⁰ = 1/1024. Bu yüzden istenen doğruluk için gereken adım sayısı önceden hesaplanabilir.'),
  ('Bir yüklem bir sayı aralığında sırayla değerlendiriliyor. Aşağıdaki sonuç dizilerinden hangisi, \'ilk DOĞRU\'nun ikili aramayla bulunabileceği türdendir?', 'Y, Y, Y, D, D, D', ['D, Y, D, Y, D, Y', 'Y, D, D, Y, Y, D, D', 'D, D, Y, Y, D, D'], 'İkili arama, yüklem bir kez DOĞRU olduktan sonra hep DOĞRU kalıyorsa çalışır. Ortaya bakıp yanlış çıkarsa sağa, doğru çıkarsa sola gidilebilir.'),
  ('Bir dizide \'tepe\', komşularından küçük olmayan elemandır. İkili aramayla tepe bulan algoritma a[orta] < a[orta + 1] durumunda ne yapar?', 'Aramayı sağ yarıda sürdürür', ['Aramayı sol yarıda sürdürür', 'a[orta]\'yı tepe olarak döndürür', 'Diziyi baştan doğrusal olarak tarar'], 'Sağa doğru değer artıyorsa, o yönde ilerledikçe ya artış sürer ve dizinin sonu tepe olur ya da bir yerde düşüş başlar; her iki durumda sağda bir tepe vardır.'),
  ('Üçlü arama (ternary search) en çok hangi tür problemi çözmek için kullanılır?', 'Tek tepeli bir fonksiyonun en büyük ya da en küçük noktasını bulmak', ['Sırasız bir dizide bir değerin bütün geçtiği konumları bulmak', 'Bir grafta en kısa yolu bulmak', 'Bir metinde bir kalıbı aramak'], 'Önce artıp sonra azalan (ya da tersi) fonksiyonlarda iki iç noktanın değerleri karşılaştırılarak uç noktanın bulunmadığı üçte bir elenir.'),
  ('Telefon rehberinde \'Şahin\' soyadını ararken rehberi ortadan değil sonlara yakın bir yerden açmak hangi arama yöntemine benzer?', 'İnterpolasyon araması', ['İkili arama', 'Üstel arama', 'Doğrusal arama'], 'İnterpolasyon araması, aranan değerin büyüklüğüne bakarak onun dizide nerede olabileceğini tahmin eder; \'Ş\' alfabenin sonlarında olduğu için rehberin sonlarına bakılır.'),
  ('İnterpolasyon araması hangi tür verilerde ortalama O(log log n) gibi ikili aramadan da hızlı bir performans gösterir?', 'Sıralı ve değerleri aşağı yukarı düzgün dağılmış veriler', ['Sırasız ve rastgele dağılmış veriler', 'Değerleri üstel olarak büyüyen ve büyük boşluklar içeren veriler', 'Bütün değerleri birbirine eşit veriler'], 'Değerler düzgün dağılmışsa doğrusal oranlama hedefin yerini çok iyi tahmin eder ve aralık hızla küçülür.'),
  ('Üstel arama, sıradan ikili aramaya göre özellikle hangi durumda üstündür?', 'Dizinin boyu bilinmediğinde ya da aranan değer başa yakın olduğunda', ['Dizi sırasız olduğunda', 'Dizide çok sayıda yinelenen değer bulunduğunda ve dizi kısa olduğunda', 'Dizi bağlı liste olarak tutulduğunda'], 'Üstel arama hedefin i konumuna göre O(log i) adım atar; dizinin sonu bilinmese bile aralığı ikiye katlayarak bir üst sınır bulur.'),
  ('Fibonacci araması, ikili aramadan farklı olarak bölme noktalarını hangi işlemle hesaplar?', 'Yalnız toplama ve çıkarmayla', ['Yalnız ikiye bölme ve aşağı yuvarlama işlemleriyle', 'Karekök alarak', 'Rastgele sayı üreterek'], 'Fibonacci araması bölme noktalarını ardışık Fibonacci sayılarıyla belirler; bölme işlemi gerektirmemesi eski donanımlarda avantaj sağlıyordu.'),
  ('Her satırı soldan sağa, her sütunu yukarıdan aşağıya artan sıralı bir matriste \'merdiven\' aramasına hangi köşeden başlanır?', 'Sağ üst köşeden', ['Sol üst köşeden', 'Matrisin tam ortasındaki hücreden', 'Sağ alt köşedeki en büyük elemandan'], 'Sağ üst köşedeki eleman satırının en büyüğü, sütununun en küçüğüdür. Hedeften büyükse sola, küçükse aşağı gidilerek her adımda bir satır ya da sütun elenir. Sol alt köşe de aynı nedenle kullanılabilir.'),
  ('m satır ve n sütunlu, satır ve sütunları artan sıralı bir matriste merdiven aramasının en kötü durumdaki adım sayısı nedir?', 'm + n mertebesinde', ['m · n mertebesinde', 'log(m · n) mertebesinde', 'm² + n² mertebesinde'], 'Her adımda ya bir sütun sola ya da bir satır aşağı gidilir; en fazla m + n − 1 adımda matrisin dışına çıkılır.'),
  ('Sıralı 1, 3, 4, 6, 9 ve 2, 3, 6, 8, 9 listelerinin ortak elemanları, iki listeyi birleştirmedeki gibi yan yana yürüyerek bulunuyor. Sonuç hangisidir?', '3, 6, 9', ['3, 6', '1, 3, 6, 9', '3, 4, 6, 8, 9'], 'İşaretçiler küçük olan taraftan ilerler; eşit değerler (3, 6 ve 9) sonuca yazılıp iki işaretçi birden ilerletilir.'),
  ('İki sıralı dizinin birleşimini yinelenenler olmadan oluşturan algoritmada iki işaretçi eşit değerleri gösterdiğinde ne yapılır?', 'Değer bir kez yazılır ve iki işaretçi de ilerletilir', ['Değer iki kez yazılır ve yalnız soldaki işaretçi ilerler', 'Değer hiç yazılmaz, iki işaretçi de ilerler', 'Algoritma durur ve kalan elemanlar eklenir'], 'Ortak değer sonuçta bir kez yer almalıdır. İki işaretçinin birlikte ilerlemesi aynı değerin ikinci kez yazılmasını önler.'),
  ('Kabarcık sıralamasında listenin sonundaki küçük değerlere \'kaplumbağa\', başındaki büyük değerlere \'tavşan\' denir. Bu adlandırmanın nedeni nedir?', 'Büyük değerler bir geçişte çok yol alırken küçükler geçiş başına yalnız bir konum ilerler', ['Küçük değerler takas edilmez, büyük değerler her geçişte iki kez takas edilir', 'Tavşanlar listeden silinir, kaplumbağalar listenin sonuna eklenir', 'Büyük değerlerin karşılaştırılması küçüklerinkinden daha uzun sürer'], 'Soldan sağa geçişte büyük bir değer art arda takaslarla sona kadar taşınabilir; sağdaki küçük değer ise her geçişte yalnız bir kez sola kayar.'),
  ('Kokteyl sıralamasının sıradan kabarcık sıralamasına göre getirdiği yenilik ve sağladığı yarar hangisidir?', 'Geçişleri sırayla iki yönde yapar; sondaki küçük değerler de hızla başa taşınır', ['Her geçişte iki eleman yerine üç eleman karşılaştırır ve takası azaltır', 'Diziyi ikiye bölüp iki yarıyı ayrı ayrı sıralayarak birleştirir', 'Takas yerine eleman kaydırarak her türlü girdide n log n süreye iner'], 'Ters yöndeki geçişler kaplumbağa sorununu giderir; ancak en kötü durumdaki karesel büyüme değişmez.'),
  ('Erken durma iyileştirmesi olmayan kabarcık sıralaması 10 elemanlı bir listeyi sıralarken, her geçişte sondaki yerleşmiş elemanları atlıyorsa toplam kaç karşılaştırma yapar?', '45', ['90', '100', '10'], 'Geçişler 9, 8, …, 1 karşılaştırma yapar; toplam 9 · 10 / 2 = 45\'tir. Bu sayı girdinin düzenine bağlı değildir.'),
  ('Bir bahçe cücesinin saksı dizerken izlediği kural şudur: önündeki saksı arkasındakinden küçük değilse bir adım ileri gider, küçükse ikisinin yerini değiştirip bir adım geri gider. Bu kural hangi sıralama algoritmasını tanımlar?', 'Cüce (gnome) sıralaması', ['Seçmeli sıralama', 'Taban (radix) sıralaması', 'Hızlı sıralama'], 'Cüce sıralaması tek bir konum değişkeniyle ilerleyip geri dönerek çalışır; iç içe döngüsü yoktur ama davranışı eklemeli sıralamaya benzer.'),
  ('Tarak sıralaması kabarcık sıralamasının hangi zayıflığını gidermek için tasarlanmıştır?', 'Sondaki küçük değerlerin çok yavaş ilerlemesini', ['Eşit değerli elemanların göreli sırasının bozulmasını', 'Ek bellek gereksinimini', 'Yalnız tam sayıları sıralayabilmesini'], 'Uzak elemanlar arasında karşılaştırma yapmak, sondaki küçük değerlerin (kaplumbağaların) tek hamlede uzun yol almasını sağlar; boşluk 1\'e inince algoritma kabarcık sıralamasına döner.'),
  ('Tarak sıralamasında boşluğu her turda küçültmek için kullanılan \'küçülme katsayısı\' için deneylerle önerilmiş yaygın değer hangisidir?', 'Yaklaşık 1,3', ['Tam 2', 'Yaklaşık 1,05', 'Tam 10'], 'Katsayı 2 gibi büyük seçilirse boşluk çok çabuk küçülür ve kaplumbağalar kalır; çok küçük seçilirse gereksiz tur yapılır. Yaklaşık 1,3 iyi bir denge verir.'),
  ('Seçmeli sıralamanın bir türü her adımda kalanların en büyüğünü bulup kalan bölümün sonuna takas ediyor. 4, 9, 2, 7, 5 listesinde ilk adımdan sonra liste nasıl olur?', '4, 5, 2, 7, 9', ['2, 9, 4, 7, 5', '4, 2, 7, 5, 9', '9, 4, 2, 7, 5'], 'En büyük eleman 9\'dur ve son konumdaki 5 ile yer değiştirir; diğer elemanlar yerinde kalır.'),
  ('İki öğretmen sınav kâğıtlarını ayrı ayrı numaraya göre sıralamış. Kâğıtları tek sıralı yığında toplamak için her seferinde iki yığının üstündeki kâğıtlardan numarası küçük olanı alıyorlar. Bu yöntem hangi algoritmanın adımıdır?', 'Birleştirmeli sıralamanın birleştirme adımı', ['Hızlı sıralamanın bölümleme adımı', 'Seçmeli sıralamanın takas adımı', 'Taban sıralamasının basamak geçişi'], 'İki sıralı dizinin en küçük başlarını karşılaştırıp küçüğü alarak ilerlemek birleştirmedir; toplam iş iki yığının kâğıt sayısıyla doğru orantılıdır.'),
  ('Donald Shell\'in özgün önerisinde boşluklar n/2\'den başlayıp her turda yarıya indirilir. 16 elemanlı bir dizide kullanılan boşluklar hangileridir?', '8, 4, 2, 1', ['16, 8, 4, 2', '15, 7, 3, 1', '13, 4, 1'], '16/2 = 8, ardından 4, 2 ve son olarak 1 boşluğu kullanılır. Son tur sıradan eklemeli sıralamadır.'),
  ('Shell sıralamasında hangi boşluk dizisi seçilirse seçilsin son boşluğun 1 olması neden zorunludur?', 'Ancak 1 boşluklu tur bütün komşu elemanları karşılaştırarak sıralamayı garanti eder', ['1 boşluğu dizinin uzunluğunu bir azaltır ve işlemi sonlandırır', 'Son turda hiç karşılaştırma yapılmadığı için toplam sürede büyük bir kazanç sağlanır', 'Boşluk 1 olmazsa algoritma ek bellek ister ve yerinde çalışamaz'], 'Daha büyük boşluklar diziyi yalnız \'h-sıralı\' yapar; bütün dizinin sıralı olması için son turda sıradan eklemeli sıralama çalışmalıdır. Önceki turlar sayesinde bu tur çok az iş yapar.'),
  ('Shell sıralaması kararlı bir algoritma değildir. Bunun nedeni hangisidir?', 'Eşit elemanlar farklı alt dizilere düşüp birbirinin önüne atlayabilir', ['Eklemeli sıralamayı hiç kullanmaması', 'Her turda dizinin tamamını ek bir diziye yeniden kopyalaması ve sırayı kaybetmesi', 'Yalnız tek sayılı boşluklar kullanması'], 'Boşluklu turlarda bir eleman uzak bir konuma taşınırken arada kalan eşit değerli bir elemanın önüne geçebilir; bu sıra son turda düzeltilmez.'),
  ('Hibbard\'ın Shell sıralaması için önerdiği boşluk dizisinin terimleri hangi biçimdedir?', '2ᵏ − 1 (1, 3, 7, 15, …)', ['2ᵏ (1, 2, 4, 8, …)', '3ᵏ (1, 3, 9, 27, 81, …)', 'k² (1, 4, 9, 16, …)'], 'Hibbard dizisinin ardışık terimleri aralarında asaldır; bu dizinin en kötü durumu O(n^(3/2)) olarak kanıtlanmıştır.'),
  ('Beden eğitimi öğretmeni öğrencileri boy sırasına sokmak için, yan yana duran iki öğrenciden uzun olan soldaysa yerlerini değiştirtiyor ve sıranın başından sonuna bunu tekrar tekrar yaptırıyor. Bu yöntem hangi algoritmaya karşılık gelir?', 'Kabarcık sıralaması', ['Seçmeli sıralama', 'Birleştirmeli sıralama', 'Sayma sıralaması'], 'Yalnız komşular karşılaştırılıp takas edilir ve geçişler tekrarlanır; her geçişte en uzun öğrenci sona doğru \'kabarır\'.'),
  ('Diziler üzerinde çalışan standart birleştirmeli sıralamanın en çok eleştirilen pratik dezavantajı hangisidir?', 'Birleştirme için girdi boyunda ek bellek gerektirmesi', ['En kötü durumda, örneğin sıralı girdide, karesel süreye düşmesi', 'Eşit elemanların sırasını bozması', 'Yalnız tam sayıları sıralayabilmesi'], 'Birleştirme sonucu ayrı bir diziye yazılır; bu O(n) ek alan demektir. Süresi ise her durumda n log n\'dir ve uygun yazılırsa kararlıdır.'),
  ('Birleştirme adımında iki dizinin baştaki elemanları eşit çıktığında, birleştirmeli sıralamanın kararlı kalması için hangi elemanın önce yazılması gerekir?', 'Soldaki (ilk) diziden gelen eleman', ['Sağdaki (ikinci) diziden gelen eleman', 'Rastgele seçilen herhangi biri', 'İkisi de yazılmadan atlanmalıdır'], 'Sol dizi, özgün dizide önce gelen elemanları içerir. Eşitlikte soldakini almak, eşit anahtarlı kayıtların başlangıç sırasını korur.'),
  ('Bağlı listeleri sıralamak için birleştirmeli sıralamanın hızlı sıralamaya göre daha uygun sayılmasının nedeni hangisidir?', 'Rastgele erişim gerektirmez ve düğümler ek dizi olmadan yeniden bağlanabilir', ['Bağlı listelerde hızlı sıralama hiç tanımlanamaz', 'Birleştirmeli sıralama bağlı listede her durumda O(n) sürede çalışabildiği için', 'Bağlı listede birleştirmeli sıralama kararsız olduğu için daha hızlıdır'], 'Birleştirme yalnız iki listenin başlarına bakarak ilerler ve işaretçileri değiştirir. Dizideki ek O(n) bellek gereği bağlı listede ortadan kalkar.'),
  ('[1, 4, 7], [2, 5, 8] ve [3, 6, 9] listeleri min-yığınla birleştirilecek. Başlangıçta yığına hangi elemanlar konur?', '1, 2 ve 3', ['1, 4 ve 7', '7, 8 ve 9', 'Bütün dokuz eleman'], 'Yığına her listenin yalnız ilk (en küçük) elemanı konur. En küçük çıkarıldıkça aynı listenin bir sonraki elemanı yığına eklenir.'),
  ('k-yollu birleştirmede yığına konan her kaydın, değerin yanında hangi bilgiyi de taşıması gerekir?', 'Değerin hangi listeden ve o listede hangi konumdan geldiğini', ['Değerin bütün listelerdeki toplam tekrar sayısını', 'Değerin ikilik tabandaki gösteriminde kaç bit tuttuğunu ve işaretini', 'Yığına kaçıncı sırada eklendiğinin karesini'], 'Bir değer çıkarıldığında aynı listenin bir sonraki elemanının yığına eklenmesi gerekir; bu da kaynağın ve konumun bilinmesini zorunlu kılar.'),
  ('Lomuto ve Hoare bölümleme yöntemleri karşılaştırıldığında, ortalamada daha az takas yapan ve bu yüzden pratikte genellikle daha hızlı olan hangisidir?', 'Hoare bölümlemesi', ['Lomuto bölümlemesi', 'İkisi her girdide tam olarak aynı sayıda takas yapar', 'Hangisinin hızlı olduğu yalnız dizinin uzunluğunun tek ya da çift olmasına bağlıdır'], 'Hoare iki uçtan içeri doğru ilerleyip yalnız yanlış taraftaki çiftleri takas eder; ortalamada Lomuto\'nun yaklaşık üçte biri kadar takas yapar.'),
  ('Hızlı sıralamanın standart dizi gerçekleştirmesi neden kararlı değildir?', 'Bölümleme sırasında elemanlar uzak konumlar arasında takas edilir', ['Pivot her zaman dizinin son elemanıdır', 'Eşit elemanlar diziden atılır', 'Özyineleme yalnız sol yarıda yapılır, sağ yarı olduğu gibi bırakılır'], 'Bir eleman takasla birden çok konum atlayabilir ve aynı anahtarlı başka bir elemanın önüne ya da arkasına geçebilir; özgün sıra korunmaz.'),
  ('Çift pivotlu hızlı sıralamada p1 ≤ p2 olan iki pivot seçilir. Bölümleme sonunda dizi hangi parçalara ayrılır?', 'p1\'den küçükler, p1 ile p2 arasındakiler ve p2\'den büyükler', ['Yalnız p1\'den küçükler ile p2\'den büyükler', 'p1\'e eşitler, p2\'ye eşitler ve geri kalan bütün elemanlar tek bir karışık grupta', 'Dizinin ilk yarısı, ikinci yarısı ve iki pivotun kendisi'], 'İki pivot diziyi üç bölgeye ayırır; her bölge ayrı ayrı özyinelemeli olarak sıralanır. Pivotlar bölgelerin arasına yerleşir.'),
  ('Yığın sıralaması diziyi artan sıraya dizmek için neden max-yığın kullanır?', 'Her adımda en büyük eleman dizinin sonundaki boşalan yere yerleşir', ['Min-yığın kullanmak diziyi her durumda ters sıralar ve ek bellek ister', 'Max-yığın kurmak min-yığından her zaman yarı yarıya daha hızlıdır', 'Max-yığında eşit elemanların sırası korunur, min-yığında korunmaz'], 'Kökteki en büyük eleman yığının son elemanıyla takas edilir ve yığın bir küçülür; böylece dizinin sonu büyükten küçüğe dolar ve ek dizi gerekmez.'),
  ('Hızlı seçme (quickselect) algoritmasının amacı ve hızlı sıralamadan temel farkı hangisidir?', 'k. en küçük elemanı bulur; bölümlemeden sonra yalnız bir tarafla devam eder', ['Bütün diziyi sıralar; bölümlemeden sonra iki tarafa da özyinelemeyle iner', 'En büyük elemanı bulur; hiçbir zaman bölümleme yapmadan diziyi tek geçişte tarar', 'Diziyi k parçaya böler; her parçayı ayrı bir işlemcide sıralayıp birleştirir'], 'Pivotun son konumu k\'den büyükse sol, küçükse sağ tarafta aranır; öbür taraf tamamen atılır. Bu yüzden ortalama süre n log n değil n\'dir.'),
  ('Rastgele pivotlu hızlı seçmenin ortalama süresi doğrusal olsa da en kötü durumu karesel olabilir. En kötü durumda da doğrusal süreyi garanti eden pivot seçim yöntemi hangisidir?', 'Medyanların medyanı', ['Üçün ortancası', 'Her zaman ilk eleman', 'Her zaman ortadaki eleman'], 'Blum, Floyd, Pratt, Rivest ve Tarjan\'ın 1973\'te verdiği yöntem pivotu beşli grupların ortancalarının ortancası olarak seçer ve her bölümlemede dizinin sabit bir oranının atılmasını garanti eder.'),
  ('Her biri 6 basamaklı onluk sayılardan oluşan bir dizi LSD (en az anlamlı basamaktan başlayan) taban sıralamasıyla sıralanacak. Kaç geçiş gerekir?', '6', ['10', '1', '60'], 'Her geçiş bir basamağa göre kararlı sıralama yapar; 6 basamak için 6 geçiş gerekir. Toplam süre geçiş sayısı çarpı (n + 10)\'dur.'),
  ('32 bitlik tam sayılar taban sıralamasıyla sıralanırken taban olarak 10 yerine 256 (bir bayt) seçilirse kaç geçiş gerekir?', '4', ['32', '8', '10'], 'Her geçiş 8 biti işler; 32 / 8 = 4 geçiş yeter. Taban büyüdükçe geçiş sayısı azalır ama her geçişteki sayaç dizisi büyür.'),
  ('MSD (en anlamlı basamaktan başlayan) taban sıralaması özellikle hangi tür veriyi sıralamak için uygundur?', 'Uzunlukları farklı olabilen dizgeleri sözlük sırasına dizmek', ['Aynı basamak sayısındaki küçük tam sayıları ters sıraya dizmek', 'Yalnız negatif tam sayılardan oluşan dizileri sıralamak', 'Kayan noktalı sayıları yuvarlamadan sıralamak'], 'MSD önce ilk karaktere göre gruplar, sonra her grubu bir sonraki karaktere göre özyinelemeli olarak böler; ortak öneki olmayan gruplar erkenden ayrılır ve kısa dizgeler doğal olarak önce gelir.'),
  ('Aynı uzunluktaki araç plakaları (ör. 06ABC12 biçiminde, 7 karakter) LSD taban sıralamasıyla sıralanıyor. İlk geçiş hangi karaktere göre yapılır?', 'En sağdaki (7.) karaktere göre', ['En soldaki (1.) karaktere göre', 'Ortadaki (4.) karaktere göre', 'Plakadaki en büyük karaktere göre'], 'LSD sıralama en az anlamlı konumdan, yani en sağdaki karakterden başlar ve sola doğru ilerler; son geçiş ilk karaktere göre yapılır.'),
  ('[0, 1) aralığında düzgün dağılmış gerçek sayılar 10 kovalı kova sıralamasıyla sıralanıyor; x sayısı ⌊10·x⌋ numaralı kovaya (0–9) konuyor. 0,78 hangi kovaya düşer?', '7', ['8', '0', '78'], '10 · 0,78 = 7,8 ve aşağı yuvarlanınca 7 bulunur. Her kova 0,1 genişliğinde bir aralığı temsil eder.'),
  ('Kova sıralamasının en kötü durumu hangi girdide ortaya çıkar?', 'Elemanların hemen tamamı aynı kovaya düştüğünde', ['Elemanlar kovalara eşit sayıda dağıldığında', 'Girdi zaten artan sırada verildiğinde', 'Kova sayısı eleman sayısına eşit seçildiğinde ve her kovaya bir eleman düştüğünde'], 'Tek kovada toplanan n eleman o kovanın iç sıralamasıyla (çoğunlukla eklemeli sıralama) karesel sürede sıralanır. Düzgün dağılımda ise beklenen süre doğrusaldır.'),
  ('Güvercin yuvası sıralaması (pigeonhole sort) sayma sıralamasından hangi yönüyle ayrılır?', 'Her değer için yalnız sayı değil, o değeri taşıyan kayıtların kendisini bir yuvada saklar', ['Elemanları yuvalara koymadan önce birbirleriyle karşılaştırarak n log n sürede sıralar', 'Yalnız değer aralığı çok geniş olan veriler için tasarlanmıştır', 'Elemanları yuvalara rastgele dağıtıp sonra birleştirir'], 'Değer aralığı kadar yuva açılır ve her kayıt kendi anahtarının yuvasına konur; yuvalar sırayla boşaltılınca kayıtlar sıralı çıkar. Sayma sıralaması ise önce yalnız sayıları tutar.'),
  ('Döngü sıralamasının (cycle sort) asıl tasarım amacı hangisidir?', 'Belleğe yazma sayısını en aza indirmek', ['Karşılaştırma sayısını n\'ye indirmek', 'Eşit elemanların sırasını korumak', 'Sıralamayı paralel işlemcilere dağıtmak'], 'Döngü sıralaması her elemanı doğrudan son konumuna yazar; yerinde olan eleman hiç yazılmaz. Karşılaştırma sayısı ise karesel kalır.'),
  ('Sıralama ağlarının temel yapı taşı olan \'karşılaştırıcı\' iki girdisiyle ne yapar?', 'Küçük değeri bir çıkışa, büyük değeri öbür çıkışa verir', ['İki girdinin toplamını ve farkını hesaplar', 'Büyük olan girdiyi tamamen siler, küçük olanı ise hiç değiştirmeden çıkışa geçirir', 'Girdileri rastgele bir sırayla iki çıkışa dağıtır'], 'Karşılaştırıcı her zaman aynı iki hattı karşılaştırır ve gerekirse değerlerin yerini değiştirir; ağdaki karşılaştırma dizisi veriden bağımsız olarak önceden sabittir.'),
  ('Aşağıdaki dizilerden hangisi bitonik bir dizidir (önce artan, sonra azalan)?', '1, 4, 6, 8, 3, 2', ['1, 4, 2, 8, 3, 6', '8, 6, 4, 2, 3, 5, 1', '2, 5, 3, 7, 1, 4'], '1, 4, 6, 8 artar ve ardından 3, 2 azalır; tek bir tepe vardır. Diğer dizilerde birden çok kez yön değişir.'),
  ('Standart bitonik sıralama ağı en doğal biçimiyle hangi girdi boyları için tanımlanır?', '2\'nin kuvveti olan boylar için', ['Yalnız tek sayılı boylar için', 'Yalnız asal sayı olan boylar için', '10\'un katı olan boylar için'], 'Ağ diziyi art arda yarıya böler; bu yüzden n = 2ᵏ olmalıdır. Başka boylarda dizi sona çok büyük değerler eklenerek tamamlanır.'),
  ('Bir kasiyer gün sonunda karışık madenî paraları önce 1, 5, 10, 25, 50 kuruş ve 1 TL\'lik bölmelere ayırıyor, sonra bölmeleri sırayla boşaltıyor. Bu işlem en çok hangi sıralama yöntemine benzer?', 'Güvercin yuvası sıralaması', ['Hızlı sıralama', 'Kabarcık sıralaması', 'Eklemeli sıralama'], 'Az sayıda olası anahtar değeri (para türü) için birer bölme ayrılır; paralar birbiriyle karşılaştırılmadan kendi bölmesine konur ve bölmeler sırayla boşaltılınca sıralı dizi elde edilir.'),
  ('Python\'un yerleşik sıralama algoritması olan Timsort\'u 2002\'de geliştiren kişi kimdir?', 'Tim Peters', ['Tony Hoare', 'Donald Knuth', 'Guido van Rossum'], 'Timsort, adını Python çekirdek geliştiricisi Tim Peters\'tan alır; birleştirmeli ve eklemeli sıralamayı gerçek verilerdeki sıralı parçaları kullanacak biçimde birleştirir.'),
  ('Timsort girdide kesin azalan bir koşu (ör. 9, 7, 4, 2) bulduğunda ne yapar?', 'Koşuyu yerinde ters çevirip artan koşu olarak kullanır', ['Koşuyu tek tek elemanlara ayırıp yeniden sıralar', 'Koşuyu dizinin sonuna taşıyıp en sonda işler', 'Koşuyu atlayıp yalnız artan koşuları birleştirir ve azalanı sona ekler'], 'Kesin azalan koşu ters çevrilince artan olur; \'kesin\' koşulu, eşit elemanların ters çevrilip kararlılığın bozulmasını önler.'),
  ('Timsort zaten sıralı n elemanlı bir diziyi ne kadar sürede işler?', 'Doğrusal sürede', ['n log n sürede', 'Karesel sürede', 'Sabit sürede'], 'Dizinin tamamı tek bir koşudur; algoritma bunu bir taramada fark eder ve birleştirme yapmadan biter.'),
  ('İçgözlemli sıralamanın (introsort) tasarımındaki temel fikir hangisidir?', 'Hızlı sıralamanın ortalama hızını yığın sıralamasının en kötü durum güvencesiyle birleştirmek', ['Birleştirmeli sıralamayı kararlı hâle getirmek için ek bir yığın yapısı kullanarak bellek kazanmak', 'Sayma sıralamasını büyük değer aralıklarına uygun hâle getirmek', 'Kabarcık sıralamasını paralel işlemcilere dağıtmak'], 'David Musser\'ın 1997\'de önerdiği yöntemde bölümleme çok derinleşirse yığın sıralamasına geçilir, küçük parçalarda ise eklemeli sıralama kullanılır.'),
  ('Python\'da sayilar = [3, 1, 2] iken x = sayilar.sort() yazılırsa x hangi değeri alır?', 'None', ['[1, 2, 3]', '[3, 1, 2]', '3'], 'list.sort() listeyi yerinde sıralar ve None döndürür; sıralı yeni bir liste isteniyorsa sorted(sayilar) kullanılmalıdır.'),
  ('JavaScript\'te [10, 9, 1].sort() çağrısı hangi diziyi üretir?', '[1, 10, 9]', ['[1, 9, 10]', '[10, 9, 1]', '[9, 10, 1]'], 'Karşılaştırma işlevi verilmezse elemanlar metne çevrilip karakter karakter karşılaştırılır; \'10\', \'9\'dan önce gelir. Sayısal sıralama için (a, b) => a − b verilmelidir.'),
  ('C dilindeki qsort işlevine verilen karşılaştırma işlevi a\'nın b\'den önce gelmesi gerektiğinde ne döndürmelidir?', 'Negatif bir sayı', ['Pozitif bir sayı', 'Sıfır', '1 ya da 0'], 'Karşılaştırıcı a < b için negatif, a = b için sıfır, a > b için pozitif değer döndürür; qsort bu işarete göre sıralar.'),
  ('C++\'ta std::sort ile std::stable_sort arasındaki temel fark nedir?', 'stable_sort eşit elemanların göreli sırasını korumayı garanti eder', ['std::sort yalnız tam sayıları, stable_sort ise her türü sıralayabilir', 'stable_sort her zaman std::sort\'tan daha hızlı ve daha az bellekle çalışır', 'std::sort sonucu ters sırada, stable_sort ise artan sırada verir'], 'std::sort genellikle içgözlemli sıralamayla yazılır ve kararlılık garantisi vermez. std::stable_sort ise birleştirmeli sıralama tabanlıdır ve ek bellek kullanabilir.'),
  ('Java\'da nesne dizileri (ör. String[]) için Arrays.sort hangi algoritmayı kullanır ve bu seçimin nedeni nedir?', 'Timsort; nesnelerde kararlılık gerektiği için', ['Çift pivotlu hızlı sıralama; en hızlısı olduğu için', 'Yığın sıralaması; ek bellek gerekmediği için', 'Kabarcık sıralaması; nesne sayısı genellikle az olduğu için'], 'Java 7\'den beri nesne dizileri kararlı olan Timsort ile, ilkel tür dizileri ise kararlılık gözlenemediği için çift pivotlu hızlı sıralamayla sıralanır.'),
  ('Python\'da bisect.insort(liste, x) çağrısı ne yapar?', 'x\'i listenin sırasını bozmayacak yere ekler', ['x\'i listenin sonuna ekleyip listeyi baştan sıralar', 'Listede x\'i ikili aramayla bulup siler', 'x\'in listede kaç kez geçtiğini ikili aramayla sayar ve döndürür'], 'insort ekleme yerini ikili aramayla O(log n) sürede bulur; ancak elemanların kaydırılması nedeniyle ekleme toplamda O(n) sürer.'),
  ('Bir sıralama işlevine verilen karşılaştırıcının \'a, b\'den önce ve b, c\'den önce ise a, c\'den önce gelir\' koşulunu sağlaması gerekir. Bu özelliğin adı nedir?', 'Geçişlilik', ['Kararlılık', 'Yerindelik', 'Uyarlanabilirlik'], 'Geçişli olmayan bir karşılaştırıcıyla \'sıralı dizi\' tanımlanamaz; algoritma her çalıştırmada farklı ve tutarsız sonuç verebilir.'),
  ('Gün adlarından oluşan bir liste (Çarşamba, Pazartesi, Cuma, …) haftadaki sırasına göre dizilecek. En doğru yaklaşım hangisidir?', 'Her güne haftadaki sıra numarasını veren bir anahtar kullanmak', ['Gün adlarını alfabetik sırayla sıralamak', 'Gün adlarını harf sayılarına göre sıralamak', 'Listeyi önce ters çevirip ardından gün adlarını alfabetik sıraya göre yeniden dizmek'], 'Alfabetik sıra \'Cuma, Cumartesi, Çarşamba, …\' gibi anlamsız bir dizilim verir. Pazartesi = 1, …, Pazar = 7 gibi bir eşleme anahtar olarak verilince haftalık sıra elde edilir.'),
  ('Sözlük (leksikografik) sırasına göre \'araba\' ile \'arabalar\' sözcüklerinden hangisi önce gelir?', 'araba', ['arabalar', 'İkisi eşit sayılır', 'Sıra, kullanılan büyük-küçük harfe göre değişir'], 'Ortak önek \'araba\' bittiğinde kısa olan sözcük önce gelir. Bir sözcük ötekinin öneki ise her zaman ondan önce sıralanır.'),
  ('Dosya adlarına numara verirken 1, 2, …, 10 yerine 001, 002, …, 010 yazmak hangi sorunu çözer?', 'Karakter karakter sıralamada dosyaların numara sırasına dizilmesini sağlar', ['Dosyaların bellekte daha az yer kaplamasını sağlar', 'Dosya adlarının büyük-küçük harfe duyarsız olmasını sağlar', 'Aynı adlı iki dosyanın oluşmasını tamamen engeller ve yedeklemeyi kolaylaştırır'], 'Basamak sayısı eşitlenince sözlük sırası sayısal sırayla çakışır: \'002\' < \'010\' doğrudur, \'2\' < \'10\' ise metin olarak yanlıştır.'),
  ('Tarihler metin olarak saklanıyor ve metin sıralamasıyla kronolojik sıraya dizilmek isteniyor. Hangi biçim bunu doğrudan sağlar?', 'YYYY-AA-GG (ör. 2021-03-15)', ['GG.AA.YYYY (ör. 15.03.2021)', 'AA/GG/YYYY (ör. 03/15/2021)', 'G Ay YYYY (ör. 15 Mart 2021, ay adı yazıyla)'], 'ISO 8601 biçiminde en önemli alan (yıl) en solda, en önemsiz alan (gün) en sağdadır ve alanlar sabit uzunluktadır; bu yüzden sözlük sırası kronolojik sıraya eşittir.'),
  ('Dış sıralama (external sorting) hangi durumda gerekir?', 'Sıralanacak veri ana belleğe sığmadığında', ['Veri yalnız tam sayılardan oluştuğunda', 'Sıralamanın birden çok işlemciyle yapılması gerektiğinde', 'Verinin internet üzerinden başka bir bilgisayara gönderileceği durumlarda'], 'Veri disk gibi yavaş bir ortamda durur; parçalar bellekte sıralanıp diske yazılır, ardından bu sıralı parçalar birleştirilir.'),
  ('1 GB ana belleği olan bir bilgisayarda 10 GB\'lık bir dosya dış birleştirmeli sıralamayla sıralanacak. Bellek dolusu parçalar sıralanıp diske yazılırsa ilk aşamada yaklaşık kaç sıralı koşu oluşur?', '10', ['1', '100', '20'], 'Her seferinde belleğe sığan 1 GB okunup sıralanır ve diske yazılır; 10 GB için yaklaşık 10 koşu oluşur. Sonra bu koşular çok yollu birleştirilir.'),
  ('Dış sıralamanın performansını belirleyen başlıca etken hangisidir?', 'Diske okuma ve yazma işlemlerinin sayısı', ['İşlemcinin yaptığı karşılaştırma sayısı', 'Bellekteki sıralamada kullanılan algoritmanın kararlılığı', 'Dosyadaki kayıtların alan sayısı ve adları'], 'Disk erişimi bellek erişiminden kat kat yavaştır. Bu yüzden amaç birleştirme turlarının, yani bütün verinin diskten okunup yazılma sayısının azaltılmasıdır.'),
  ('Basılı sözlüklerin kenarındaki harf sekmeleri önce harfin başladığı bölüme atlamayı, sonra o bölümde aramayı sağlar. Bu düzen hangi arama fikrine en yakındır?', 'Önce kaba bir dizinle bloğu bulup sonra blok içinde aramak', ['Bütün sözlüğü ilk sayfadan başlayarak taramak', 'Sayfaları rastgele açıp sözcüğü denemek', 'Sözlüğü her aramadan önce yeniden alfabetik sıraya koymak'], 'Harf sekmeleri iki düzeyli bir dizin gibidir: sıçramalı aramada olduğu gibi önce doğru blok bulunur, ardından blok içinde ilerlenir.'),
  ('Bir sıralama algoritmasının \'uyarlanabilir\' (adaptive) olması ne demektir?', 'Girdi önceden ne kadar sıralıysa o kadar hızlı çalışması', ['Her türlü veri türünü sıralayabilmesi', 'Bellek azaldığında daha az bellekle çalışabilmesi', 'İşlemci sayısına göre kendini paralelleştirmesi ve hızlanması'], 'Eklemeli sıralama ve Timsort, neredeyse sıralı girdide doğrusala yaklaşır; seçmeli sıralama ise girdinin düzeninden bağımsız olarak aynı sayıda karşılaştırma yapar.'),
  ('Aşağıdaki sıralama algoritmalarından hangisi uyarlanabilir (adaptive) değildir?', 'Seçmeli sıralama', ['Eklemeli sıralama', 'Timsort', 'Doğal birleştirmeli sıralama'], 'Seçmeli sıralama her adımda kalan bütün elemanları tarar; dizi baştan sıralı olsa bile n(n − 1)/2 karşılaştırma yapar.'),
  ('Çakışan aralıkları birleştirme algoritmasında aralıkların önce başlangıç noktalarına göre sıralanmasının yararı nedir?', 'Çakışan aralıklar yan yana gelir ve tek bir taramada birleştirilebilir', ['Aralıkların uzunlukları kendiliğinden eşitlenir', 'Birleştirme sonucunda aralık sayısı her durumda tam olarak yarıya iner', 'Bitiş noktalarına hiç bakmaya gerek kalmaz'], 'Sıralamadan sonra bir aralık yalnız kendisinden önce gelen birleşik aralıkla çakışabilir; bu yüzden n log n sıralama ve doğrusal bir tarama yeter.'),
  ('\'ankara\' sözcüğünün harfleri sayma sıralamasıyla (her harfin kaç kez geçtiği sayılıp alfabe sırasıyla yazılarak) sıralanıyor. Sonuç nedir?', 'aaaknr', ['aakknr', 'ankara', 'rnkaaa'], 'Sayımlar a: 3, k: 1, n: 1, r: 1\'dir. Harfler alfabe sırasıyla sayıları kadar yazılınca \'aaaknr\' elde edilir; harfler birbiriyle karşılaştırılmaz.'),
  ('Anagram gruplamada her sözcüğün harfleri alfabetik sıralanarak bir anahtar elde ediliyor. \'kalp\' sözcüğü ile aynı gruba düşen sözcük hangisidir?', 'plak', ['park', 'kapı', 'kalıp'], '\'kalp\' ve \'plak\' sözcüklerinin harfleri sıralanınca ikisi de \'aklp\' anahtarını verir. \'park\' r, \'kapı\' ı içerir; \'kalıp\' fazladan ı harfi taşır.'),
  ('İki listenin, sıraları farklı olsa da tamamen aynı elemanları aynı sayıda içerip içermediğini anlamanın basit bir yolu hangisidir?', 'İki listeyi de sıralayıp eleman eleman karşılaştırmak', ['İki listenin yalnız en büyük elemanlarını karşılaştırmak', 'İki listenin uzunluklarını karşılaştırmak', 'Listelerden birini ters çevirip ötekiyle eleman eleman karşılaştırmak ve fark yoksa eşit saymak'], 'Sıralama her listeyi aynı \'kanonik\' biçime getirir; içerik aynıysa sıralı hâlleri birebir aynı olur. Toplam süre n log n\'dir.'),
  ('Bir dizide yalnız en küçük 3 eleman sıralı biçimde isteniyor. Seçmeli sıralamanın yalnız ilk 3 adımını çalıştırmak kaç karşılaştırma gerektirir (n elemanlı dizi)?', 'Yaklaşık 3n', ['Yaklaşık n²/2', 'Yaklaşık n log n', 'Tam olarak 3'], 'Her adım kalanların en küçüğünü bulmak için doğrusal tarama yapar; 3 adım yaklaşık 3n karşılaştırmadır. k küçük olduğu sürece bu O(nk) yöntemi pratiktir.'),
  ('Python\'da heapq.nlargest(3, notlar) çağrısı ne döndürür?', 'En büyük üç notu büyükten küçüğe sıralı bir liste olarak', ['Notlar listesinin ilk üç elemanını değiştirmeden', 'En büyük notun kaç kez geçtiğini sayı olarak', 'Notları üçerli gruplara ayıran ve her grubun en büyüğünü veren bir liste'], 'nlargest, yığın kullanarak en büyük k elemanı bulur ve azalan sırada döndürür; bütün listeyi sıralamaktan daha az iş yapar.'),
  ('Kabarcık sıralaması 10 000 elemanlı bir diziyi 2 saniyede sıralıyor. Aynı türden 20 000 elemanlı bir dizi için süre yaklaşık ne kadar olur?', '8 saniye', ['4 saniye', '2 saniye', '16 saniye'], 'Karesel büyüyen algoritmada boyut iki katına çıkınca iş 2² = 4 katına çıkar: 2 · 4 = 8 saniye.'),
  ('MapReduce gibi dağıtık veri işleme sistemlerinde \'map\' ile \'reduce\' aşamaları arasındaki karıştırma (shuffle) aşamasında anahtarlarla ilgili ne yapılır?', 'Ara çıktılar anahtara göre gruplanıp sıralanır', ['Anahtarlar rastgele silinir', 'Anahtarlar şifrelenip sıkıştırılır', 'Bütün anahtarlar tek bir sayıya toplanır ve sonuç yazılır'], 'Her reduce işi kendine düşen anahtar aralığındaki kayıtları sıralı ve gruplanmış olarak alır; böylece aynı anahtarlı değerler art arda işlenebilir. Bu aşama özünde büyük ölçekli bir dış sıralamadır.'),
  ('Horspool algoritmasında metindeki, kalıbın son konumuna denk gelen karakter kalıpta hiç geçmiyorsa ne yapılır?', 'Kalıp, kendi uzunluğu kadar kaydırılır', ['Kalıp yalnız bir konum kaydırılır', 'Arama durdurulur ve \'bulunamadı\' denir', 'Kalıp metnin başına geri götürülüp arama yeniden başlatılır'], 'O karakteri içeren hiçbir hizalama eşleşemeyeceği için kalıp tamamen onun ötesine atlatılır. Uzun kalıplarda ve geniş alfabede bu atlamalar aramayı çok hızlandırır.'),
  ('Uzun bir metnin sonek dizisi bir kez oluşturulduktan sonra bir kalıbın metinde geçip geçmediği nasıl hızlı bulunur?', 'Sıralı sonekler üzerinde ikili arama yapılarak', ['Sonek dizisi baştan sona doğrusal olarak taranarak', 'Kalıbın harfleri sıralanıp sonek dizisine eklenerek', 'Metin kalıbın uzunluğuna bölünerek ve her parça ayrı ayrı karşılaştırılarak'], 'Kalıbı içeren her konum, kalıpla başlayan bir sonektir; sonekler sıralı olduğundan bunlar ardışık bir blok oluşturur ve yaklaşık m log n karşılaştırmayla bulunur.'),
  ('Sabır sıralaması bütün kartları dağıttıktan sonra sıralı çıktıyı nasıl üretir?', 'Her biri kendi içinde sıralı olan yığınları k-yollu birleştirerek', ['Yığınları soldan sağa sırayla uç uca ekleyerek', 'Yalnız en uzun yığını alıp geri kalanları atarak', 'Bütün yığınları karıştırıp kartları yeniden dağıtarak ve işlemi tekrarlayarak'], 'Her yığında üstten alta kartlar artan sıradadır; tepe kartları bir min-yığında tutularak yığınlar birleştirilir ve sıralı dizi elde edilir.'),
  ('Yalnız 8 elemandan oluşan ve neredeyse sıralı olan bir dizi sıralanacak. Hangi algoritma pratikte en uygundur?', 'Eklemeli sıralama', ['Taban sıralaması', 'Dış birleştirmeli sıralama', 'Bitonik sıralama ağı'], 'Küçük boyut ve neredeyse sıralı girdi eklemeli sıralamanın en güçlü olduğu durumdur: ek yükü yoktur ve ters çift sayısı kadar iş yapar.'),
  ('Bir öğrenci, sıralı olmayan 20 kitaplık bir rafta adı verilen bir kitabı bir kez bulacak. Aşağıdaki stratejilerden hangisi en az işle sonuca ulaşır?', 'Kitapları sırayla kontrol edip bulunca durmak', ['Önce bütün kitapları alfabetik dizip sonra ortadan aramak', 'Kitapları önce boylarına göre dizip sonra ikili arama yapmak', 'Rafı ikiye bölüp her yarıyı ayrı ayrı alfabetik sıraya koymak ve sonra aramak'], 'Tek seferlik aramada sıralamanın maliyeti hiçbir zaman geri kazanılmaz; doğrusal arama en fazla 20 kontrolle biter. Boya göre sıralama ise ada göre aramaya hiç yardım etmez.'),
  ('Artan sırada sıralanmış bir dizi azalan sıraya getirilecek. En verimli yol hangisidir?', 'Diziyi tek geçişte ters çevirmek', ['Diziyi ters karşılaştırıcıyla baştan sıralamak', 'Dizide her elemanı ikili aramayla bulup yer değiştirmek', 'Diziyi rastgele karıştırıp azalan sıraya göre yeniden sıralamak'], 'Sıralı dizinin tersi zaten azalan sıradadır; iki uçtan ortaya doğru takas O(n) sürer. Yeniden sıralamak gereksiz yere n log n iş yapar.'),
  ('Bir dizide sıfırların hepsi, sıfır olmayan elemanların göreli sırası korunarak sona taşınacak: 0, 3, 0, 1, 2 → 3, 1, 2, 0, 0. Bu işlem hangi tür bölümlemedir?', 'Kararlı bölümleme', ['Lomuto bölümlemesi', 'Üç yollu bölümleme', 'Rastgele pivotlu Hoare bölümlemesi'], 'Dizi bir koşula göre ikiye ayrılıyor ve her grubun içindeki sıra korunuyor. Bir yazma işaretçisiyle sıfır olmayanları sırayla öne yazıp kalan yerleri sıfırla doldurmak bunu O(n)\'de yapar.'),
  ('Bir öğrenci hesap tablosu programında yalnız \'Not\' sütununu seçip sıralıyor; \'Ad\' sütunu yerinde kalıyor. Sonuç ne olur?', 'Notlar başka öğrencilerin adlarıyla eşleşir ve kayıtlar bozulur', ['Adlar da otomatik olarak notlarla birlikte yer değiştirir ve sorun çıkmaz', 'Notlar sıralanmaz, çünkü tek sütun sıralanamaz', 'Tablo kendiliğinden ada göre ikinci kez sıralanır ve eşleşme korunur'], 'Bir kaydın alanları birlikte taşınmalıdır. Yalnız bir sütun sıralanırsa satırlar arasındaki ilişki kopar; sıralama bütün satırlar üzerinde bir anahtara göre yapılmalıdır.'),
  ('Python\'da bir listede bulunmayan bir değer için liste.index(değer) çağrılırsa ne olur?', 'ValueError hatası oluşur', ['−1 döndürülür', 'None döndürülür', 'Listenin uzunluğu döndürülür'], 'list.index doğrusal arama yapar ve değeri bulamazsa istisna fırlatır. Hata istenmiyorsa önce \'değer in liste\' ile denetlenmelidir.'),
  ('Python\'da metin.find(\'x\') ile metin.index(\'x\') arasındaki fark, \'x\' metinde yoksa nasıl ortaya çıkar?', 'find −1 döndürür, index hata fırlatır', ['find hata fırlatır, index −1 döndürür', 'İkisi de None döndürür', 'find 0 döndürür, index ise metnin uzunluğunu döndürür'], 'İki yöntem de alt dizgeyi soldan arar ve bulduğunda ilk konumu verir. Fark yalnız bulunamama durumundadır: find −1, index ise ValueError verir.'),
  ('Unix\'te yinelenen satırları ayıklamak için uniq komutunun önüne neden genellikle sort konur (sort dosya | uniq)?', 'uniq yalnız art arda gelen aynı satırları birleştirir', ['uniq yalnız sayılardan oluşan satırları işleyebilir', 'sort satırları uniq\'in okuyabileceği ikili biçime dönüştürür', 'uniq kendi başına çalıştırıldığında dosyayı silen bir komuttur'], 'Aynı satırlar dosyanın farklı yerlerindeyse uniq bunları fark etmez. Sıralama, eşit satırları yan yana getirerek uniq\'in hepsini yakalamasını sağlar.'),
  ('Unix\'te \'sort −k2 dosya.txt\' komutu ne yapar?', 'Satırları ikinci alandan başlayarak sıralar', ['Dosyanın yalnız ilk iki satırını sıralar', 'Satırları iki kez art arda sıralar', 'Her satırdaki ikinci karakteri siler ve kalan satırları sıralar'], '−k seçeneği sıralama anahtarının hangi alandan başladığını belirtir; alanlar varsayılan olarak boşluklarla ayrılır. Örneğin \'ad soyad\' satırları soyada göre dizilebilir.'),
  ('C standart kütüphanesinde sıralı bir dizide ikili arama yapan ve qsort ile aynı biçimde karşılaştırma işlevi alan işlev hangisidir?', 'bsearch', ['strstr', 'memcmp', 'lsearch'], 'bsearch, aranan anahtarı ve sıralı diziyi alır; bulursa elemanın adresini, bulamazsa NULL döndürür. Dizinin aynı karşılaştırma işleviyle sıralanmış olması gerekir.'),
  ('Farklı sürelerdeki işler birkaç makineye dağıtılırken \'en uzun iş önce\' (LPT) kuralı uygulanıyor. Bu kural sıralamayı nasıl kullanır?', 'İşleri süreye göre azalan sıraya dizip her birini o an en az yüklü makineye verir', ['İşleri süreye göre artan sıraya dizip tamamını sırayla yalnız ilk makineye vererek öteki makineleri boş bırakır', 'Makineleri hıza göre sıralayıp her işi en hızlı makineye verir', 'İşleri adlarına göre sıralayıp makinelere sırayla birer birer verir'], 'Uzun işlerin önce yerleştirilmesi, sona kalan büyük bir işin bir makineyi aşırı yüklemesini önler. Bu açgözlü yöntem en iyi çözüme yakın sonuç verir.'),
  ('200 ölçüm küçükten büyüğe sıralandı. Basit \'en yakın sıra\' tanımıyla 90. yüzdelik değer yaklaşık kaçıncı sıradaki ölçümdür?', '180.', ['90.', '20.', '190.'], 'Ölçümlerin %90\'ı bu değerin altında kalmalıdır: 0,90 · 200 = 180. Yüzdelikler, sıralı veride ilgili sıradaki değere bakılarak bulunur.'),
  ('Basılı bir telefon rehberi soyada göre sıralı. Elinizde yalnız bir telefon numarası varsa sahibini bulmak için hangi arama gerekir ve neden?', 'Doğrusal arama; rehber numaraya göre sıralı değildir', ['İkili arama; rehber zaten sıralıdır', 'İnterpolasyon araması; numaralar düzgün dağılmıştır', 'Üstel arama; aranan numara büyük olasılıkla rehberin başına yakın bir yerdedir'], 'Bir sıralama yalnız kendi anahtarına göre hızlı aramaya izin verir. Numaraya göre arama için ya bütün rehber taranmalı ya da numaraya göre sıralı ikinci bir dizin hazırlanmalıdır.'),
  ('\'Boncuk sıralaması\' (bead sort) her sayıyı dikey çubuklar üzerinde bir sıra boncukla gösterir ve boncukların yerçekimiyle aşağı düşmesine izin verir. Bu yöntem hangi tür sayılarla çalışır?', 'Yalnız pozitif tam sayılarla', ['Her türlü gerçek sayıyla', 'Yalnız negatif sayılarla', 'Yalnız metinlerle ve harflerle'], 'Bir sayı kadar boncuk konabilmesi için değerlerin pozitif tam sayı olması gerekir. Boncuklar düşünce her satırdaki boncuk sayısı sıralı sayıları verir.'),
  ('Hızlı sıralamanın ek bellek gereksinimi (özyineleme yığını) ortalama durumda hangi mertebededir?', 'log n', ['n', '1', 'n log n'], 'Dengeli bölümlemelerde iç içe çağrı derinliği log n\'dir ve her çağrı sabit yer tutar. Dizinin kendisi yerinde düzenlendiği için ayrıca kopya gerekmez.'),
  ('Gerçek sayılarda ikili arama yapılırken \'alt ≤ üst\' gibi bir döngü koşulu neden uygun değildir ve yerine ne kullanılır?', 'Aralık hiç tam sıfıra inmeyebilir; üst − alt < ε olunca ya da belirli sayıda adımda durulur', ['Gerçek sayılar karşılaştırılamaz; arama tam sayılara çevrilip yapılır', 'Gerçek sayılarda orta nokta hesaplanamaz; aralığın ucu kullanılır', 'Döngü ilk adımda biter; aralık her zaman tek noktadır ve sonuç hemen bulunur'], 'Kayan noktalı sayılarda alt ve üst birbirine sonsuza dek yaklaşır ama eşit olmayabilir. Bu yüzden istenen duyarlılık (ε) ya da sabit bir yineleme sayısı durma ölçütü olur.'),
  ('Kabarcık sıralamasının iç döngüsü \'j, 0\'dan n − 1\'e kadar\' yazılmış ve döngüde a[j] ile a[j + 1] karşılaştırılıyor (indisler 0\'dan). Bu kodun hatası nedir?', 'Son adımda a[n] okunur ve dizinin dışına taşılır', ['İlk eleman hiç karşılaştırılmaz', 'Dizi ters sıraya dizilir', 'Takaslar yalnız tek indislerde yapılır ve dizi sıralanmaz'], 'j = n − 1 olduğunda a[j + 1] = a[n] olur; n elemanlı dizide geçerli son indis n − 1\'dir. Döngü n − 2\'de (her geçişte daha erken) bitmelidir.'),
  ('\'İplik sıralaması\' (strand sort) her turda ne yapar?', 'Listeden artan bir alt diziyi çekip sonuç listesiyle birleştirir', ['Listenin en büyük elemanını bulup başa takas eder', 'Listeyi iki eşit parçaya bölüp ayrı ayrı sıralar', 'Listedeki komşu çiftleri karşılaştırıp yer değiştirir ve en küçüğü sona taşır'], 'Her turda ilk elemandan başlayıp kendinden büyük olanları alarak bir \'iplik\' oluşturur, bu artan dizi şimdiye kadarki sonuçla birleştirilir. Neredeyse sıralı listelerde hızlıdır.'),
  ('Kokteyl sıralamasında bir ileri ve bir geri geçiş tamamlandığında dizinin hangi konumlarındaki elemanların kesin yerinde olduğu garanti edilir?', 'Hem en sondaki hem en baştaki konum', ['Yalnız en sondaki konum', 'Yalnız dizinin ortasındaki konum, uçlar ise henüz kesin değildir', 'Dizinin tamamı'], 'İleri geçiş en büyüğü sona, geri geçiş en küçüğü başa taşır. Her turda sıralanacak bölge iki uçtan birer eleman daralır.'),
  ('Shell sıralamasında boşluk dizisi olarak yalnız 1 kullanılırsa algoritma hangi sıralamaya dönüşür?', 'Eklemeli sıralama', ['Kabarcık sıralaması', 'Seçmeli sıralama', 'Birleştirmeli sıralama'], 'Shell sıralaması her boşlukta eklemeli sıralama yapar; tek boşluk 1 ise baştan sona sıradan eklemeli sıralama çalışır ve önceki turların kazancı olmaz.'),
  ('Ekran kartlarında (GPU) çok sayıda tam sayı anahtarı sıralamak için en yaygın kullanılan algoritma ailesi hangisidir?', 'Taban sıralaması', ['Kabarcık sıralaması', 'Gözleme sıralaması', 'Eklemeli sıralama'], 'Taban sıralamasının her geçişi sayma, önek toplamı ve dağıtma adımlarından oluşur; bunlar binlerce çekirdeğe kolayca bölünür ve karşılaştırma gerektirmez.'),
  ('\'Doğal sıralama\' (natural sort) yapan bir karşılaştırıcı \'resim9.png\' ile \'resim10.png\' adlarını nasıl karşılaştırır?', 'Adları harf ve sayı parçalarına ayırıp sayı parçalarını sayısal değer olarak karşılaştırır', ['Adları sondan başa doğru karakter karakter karşılaştırır', 'Adların yalnız uzunluklarına bakar ve kısayı önce koyar', 'Adlardaki bütün rakamları tamamen siler ve geriye kalan harf kısımlarını karakter karakter karşılaştırarak sıralar'], '\'resim\' parçaları eşittir; ardından 9 ile 10 sayı olarak karşılaştırılır ve 9 < 10 olduğundan \'resim9.png\' önce gelir. Karakter karşılaştırmasında ise \'1\' < \'9\' olduğundan sıra tersine dönerdi.'),
  ('Bir müşteri veritabanında telefon numaraları \'0532 123 45 67\', \'+90 532 1234567\' gibi farklı biçimlerde girilmiş. Bir numaranın kayıtlarda olup olmadığını güvenilir biçimde aramak için önce ne yapılmalıdır?', 'Bütün numaraları tek bir standart biçime dönüştürmek', ['Numaraları uzunluklarına göre sıralamak', 'Yalnız ilk dört rakama göre arama yapmak', 'Numaraları rastgele karıştırıp ardından her kaydı tek tek eldeki numarayla karakter karakter karşılaştırmak'], 'Aynı numaranın farklı yazımları karakter karşılaştırmasında eşleşmez. Boşluklar atılıp ülke kodu ve baştaki sıfır tek bir kurala göre düzenlenirse hem arama hem sıralama doğru çalışır.'),
  ('Soyadlarını yazılışlarına değil söylenişlerine göre gruplayıp \'Smith\' ile \'Smyth\' gibi adları aynı kodla eşleştiren, nüfus kayıtlarında arama için geliştirilmiş klasik algoritma hangisidir?', 'Soundex', ['Huffman kodlaması', 'Rabin–Karp', 'Base64 kodlaması'], 'Soundex her adı ilk harf ve üç rakamdan oluşan bir koda çevirir; benzer sesli ünsüzler aynı rakamı alır. Böylece yazımı farklı ama söylenişi benzer adlar aynı kodla bulunur.'),
  ('Dosya adı aramasında \'dosya?.txt\' kalıbı kullanılıyor (\'?\' tam olarak bir karakter yerine geçer). Aşağıdaki dosyalardan hangisi bu kalıpla eşleşir?', 'dosya1.txt', ['dosya10.txt', 'dosya.txt', 'dosya1.doc'], '\'?\' tek bir karakteri temsil eder; \'dosya10.txt\' iki karakter, \'dosya.txt\' sıfır karakter içerir. \'dosya1.doc\' ise uzantı nedeniyle eşleşmez.'),
  ('Bir arama motoru milyonlarca belgede sözcük aramak için \'ters dizin\' (inverted index) kullanıyor. Bu yapı nedir?', 'Her sözcük için o sözcüğün geçtiği belgelerin listesi', ['Her belge için sözcüklerinin ters sırayla yazılmış hâli', 'Belgelerin sondan başa doğru numaralandırılmış listesi', 'Her harf için o harfle başlayan belgelerin sayısı'], 'Sorgu geldiğinde belgeler taranmaz; sözcüğün listesine doğrudan gidilir. Birden çok sözcüklü sorgularda sıralı listelerin kesişimi alınır.'),
  ('C++\'ta sıralı bir vektörde std::equal_range(v.begin(), v.end(), x) çağrısı ne döndürür?', 'x\'e eşit elemanları kapsayan aralığın başlangıç ve bitiş konumlarını', ['Yalnız x\'in var olup olmadığını belirten bir mantıksal değeri', 'x\'e en yakın iki elemanın değerlerini, biri x\'ten küçük biri büyük olacak biçimde', 'Vektörün x\'ten büyük bütün elemanlarını içeren yeni bir vektörü'], 'equal_range, lower_bound ve upper_bound\'un sonucunu bir çift olarak verir; ikisinin farkı x\'in kaç kez geçtiğidir.'),
  ('C++\'taki std::binary_search işlevi ne döndürür?', 'Değerin bulunup bulunmadığını gösteren true ya da false', ['Bulunan elemanın indisini', 'Bulunan elemanı gösteren bir yineleyiciyi', 'Değer yoksa ekleneceği yeri gösteren negatif bir sayıyı, varsa indisini'], 'binary_search yalnız var/yok bilgisini verir. Konum gerekiyorsa lower_bound kullanılır ve döndürdüğü yineleyicinin gösterdiği elemanın x\'e eşit olup olmadığına bakılır.'),
  ('JavaScript\'te dizi.sort() ile dizi.toSorted() arasındaki fark nedir?', 'sort diziyi yerinde değiştirir, toSorted sıralı yeni bir kopya döndürür', ['sort kararlıdır, toSorted kararsızdır', 'sort yalnız sayıları, toSorted yalnız metinleri sıralar', 'toSorted azalan, sort ise artan sırada sıralar ve ikisi de diziyi değiştirmez'], 'ES2023\'te eklenen toSorted özgün diziye dokunmaz. sort ise diziyi yerinde sıralar ve aynı diziyi döndürür; ES2019\'dan beri ikisi de kararlıdır.'),
  ('4 haneli bir sayısal şifre (0000–9999) kaba kuvvetle, her olasılık sırayla denenerek aranıyor. En kötü durumda kaç deneme gerekir?', '10 000', ['9 999', '4 000', '40'], 'Her hane 10 değer alabilir ve haneler bağımsızdır: 10⁴ = 10 000 olasılık vardır. Şifre son denenen olabilir.'),
  ('Sudoku çözen bir geri izleme algoritması bir hücreye yazdığı rakamın satır, sütun ya da kutu kuralını bozduğunu görünce ne yapar?', 'O dalı bırakıp aynı hücre için sıradaki rakamı dener', ['Bulmacanın tamamını silip baştan başlar', 'Kuralı bozan rakamı yine de bırakıp sonraki hücreye geçer', 'Bütün boş hücrelere aynı rakamı yazar ve sonra denetler'], 'Kuralı bozan kısmi çözümden hiçbir geçerli çözüm çıkamayacağı için o dalın altındaki bütün olasılıklar budanır. Bu budama, kaba kuvvete göre arama uzayını büyük ölçüde küçültür.'),
  ('Tepe tırmanma (hill climbing) araması her adımda yalnız daha iyi bir komşuya geçer. Bu yöntemin bilinen zayıflığı nedir?', 'Yerel bir tepeye takılıp en iyi çözümü kaçırabilir', ['Her zaman en kötü çözümü bulur', 'Komşu çözümleri hiç değerlendirmez', 'Arama uzayının tamamını tek tek taramadan hiçbir zaman duramaması ve çok yavaş olması'], 'Bütün komşular daha kötüyse algoritma durur; bu nokta yalnız yerel bir en iyi olabilir. Rastgele yeniden başlatma ya da benzetimli tavlama bu sorunu hafifletir.'),
  ('Benzetimli tavlama (simulated annealing) yerel aramanın hangi davranışını değiştirerek yerel tepelerden kurtulmayı amaçlar?', 'Zaman zaman, olasılığı giderek azalan biçimde daha kötü çözümleri de kabul eder', ['Her adımda bütün komşuları sıralayıp yalnız en iyisini seçer ve hiçbir zaman geri adım atmaz', 'Arama uzayını ikiye bölüp ikili arama yapar', 'Yalnız başlangıç çözümünü değerlendirip durur'], 'Metal tavlamadaki soğumaya benzer biçimde \'sıcaklık\' yüksekken kötü hamleler sık kabul edilir; sıcaklık düştükçe algoritma iyileştirici adımlara yönelir.'),
  ('Python\'da sorted([True, False, True]) ifadesinin sonucu nedir?', '[False, True, True]', ['[True, True, False]', '[True, False, True]', 'TypeError'], 'Python\'da False 0, True 1 gibi davranır; bu yüzden artan sırada False önce gelir.'),
  ('Python\'da bir listede \'x in liste\' ifadesi hangi arama yöntemiyle değerlendirilir?', 'Doğrusal arama', ['İkili arama', 'İnterpolasyon araması', 'Üstel arama'], 'Liste sıralı olsa bile \'in\' bunu bilemez; elemanlara baştan sırayla bakar. Sıralı listede hızlı arama için bisect modülü kullanılmalıdır.'),
  ('Bir programcı \'sorted(liste)\' yazıyor ama sonucu hiçbir değişkene atamıyor ve ardından listeyi yazdırıyor. Ekranda ne görür?', 'Listenin özgün, sırasız hâlini', ['Listenin sıralı hâlini', 'Boş bir listeyi', 'None değerini, çünkü sorted listeyi silip yerine None koyar'], 'sorted özgün listeyi değiştirmez, yeni bir liste üretir; atanmayan sonuç kaybolur. Yerinde sıralama için liste.sort() kullanılmalıdır.'),
  ('\'Bingo sıralaması\' seçmeli sıralamanın bir türüdür ve her geçişte en küçük değeri bulduktan sonra ne yapar?', 'O değere eşit bütün elemanları tek geçişte öne taşır', ['Yalnız en küçük elemanı sona taşır', 'Diziyi en küçük değerle ikiye böler ve iki yarıyı ayrı ayrı yeniden sıralamak üzere işaretler', 'En küçük değeri diziden siler ve dizi kısalır'], 'Çok sayıda yinelenen değer olan dizilerde, her farklı değer için tek geçiş yeterli olur; geçiş sayısı eleman sayısına değil farklı değer sayısına bağlı kalır.'),
  ('Düzlemdeki en yakın iki noktayı bulan böl ve yönet algoritması işe noktaları neye göre sıralayarak başlar?', 'x koordinatlarına göre', ['Orijine uzaklıklarına göre', 'Girilme sıralarına göre', 'Koordinatlarının toplamına göre ve büyükten küçüğe'], 'Noktalar x\'e göre sıralanıp ortadan ikiye bölünür; iki yarının en yakın çiftleri özyinelemeyle bulunur ve sınır şeridindeki noktalar ayrıca denetlenir. Toplam süre n log n\'dir.'),
  ('Burrows–Wheeler dönüşümü (bzip2 sıkıştırmasında kullanılır) bir metin üzerinde hangi sıralamayı yapar?', 'Metnin bütün döndürülmüş hâllerini sözlük sırasına dizer', ['Metnin harflerini sıklığa göre dizer', 'Metnin sözcüklerini uzunluğa göre dizer', 'Metnin satırlarını sondan başa doğru dizer ve her satırın ilk harfini ayrı bir listeye yazar'], 'Dönüşümün çıktısı sıralı döndürmelerin son karakterlerinden oluşur; benzer bağlamdaki karakterler yan yana geldiği için sonuç daha iyi sıkıştırılır.'),
  ('Bazı ders kitaplarındaki birleştirme işlevi, iki alt dizinin sonuna \'sonsuz\' değerli birer gözcü ekler. Bunun amacı nedir?', 'Dizilerden birinin bitip bitmediğini her adımda denetleme gereğini kaldırmak', ['Birleştirmeyi kararsız hâle getirmek', 'Dizilerin boylarını eşitlemek için ek kopyalama yapmadan bellekte yer ayırmak ve taşmayı önlemek', 'Sonuçtaki en büyük elemanı bulmayı kolaylaştırmak'], 'Bir dizi bittiğinde başında sonsuz durur ve hiçbir zaman seçilmez; böylece döngü tam n kez döner ve sınır denetimi gerekmez.'),
  ('Bir okuldaki 9 öğrencinin yaşları için sayaç tablosu 15: 4, 16: 3, 17: 2 biçimindedir. Yaşlar sıralanmadan, sayaçlar birikimli toplanarak ortanca bulunursa sonuç kaçtır?', '16', ['15', '17', '15,5'], 'Ortanca 5. değerdir. 15 yaşındakiler ilk 4 sırayı tutar; 16\'lar 5.–7. sıraları kaplar. Bu yüzden ortanca 16\'dır.'),
  ('Özyinelemeli birleştirmeli sıralamada \'dizi tek elemanlı ya da boşsa olduğu gibi döndür\' satırı unutulursa ne olur?', 'Özyineleme hiç durmaz ve sonunda yığın taşması oluşur', ['Dizi ters sırada döner', 'Algoritma kararsız hâle gelir', 'Yalnız tek elemanlı diziler yanlış sıralanır, gerisi doğrudur'], 'Temel durum olmadan tek elemanlı dizi de yeniden bölünmeye çalışılır; boş ve tek elemanlı parçalar sonsuza dek bölünür ve çağrı yığını taşar.'),
  ('Doğrusal arama işlevinde döngünün içinde \'eğer a[i] = x ise i döndür; değilse −1 döndür\' yazılmış. Bu kodun hatası nedir?', 'Yalnız ilk eleman denetlenir; eşleşmezse arama hemen biter', ['Son eleman hiç denetlenmez', 'Bulunan değerin yerine bir sonraki indis döner', 'Dizi boşsa döngü hiç bitmez ve program sonsuz döngüye girer'], '\'değilse −1 döndür\' ilk turda çalışır ve işlev ilk elemandan sonra çıkar. −1 döndürme satırı döngüden sonra, bütün elemanlar denetlendikten sonra yer almalıdır.'),
  ('Bir kullanıcı metin dosyasındaki satırları büyükten küçüğe (ters alfabetik) dizmek için Unix sort komutuna hangi seçeneği eklemelidir?', '−r', ['−u', '−k', '−c'], '−r (reverse) karşılaştırma sonucunu tersine çevirir; −u yinelenenleri atar, −k anahtar alanı seçer. Sayısal azalan sıra için −nr birlikte kullanılır.'),
  ('Unix\'teki grep komutunun temel işi nedir?', 'Bir kalıpla eşleşen satırları dosyada arayıp yazdırmak', ['Dosyadaki satırları alfabetik sıraya dizmek', 'Dosyadaki yinelenen satırları birleştirmek', 'Dosyanın boyutunu bayt cinsinden hesaplayıp satır sayısıyla birlikte ekrana yazdırmak'], 'grep (global regular expression print) metin dosyalarında satır satır arama yapar; −i seçeneği büyük-küçük harfi yok sayar, −c eşleşen satırları sayar.'),
  ('JavaScript\'te dizi.find(kosul) ile dizi.filter(kosul) arasındaki fark nedir?', 'find koşulu sağlayan ilk elemanı, filter ise bütün eşleşmeleri içeren yeni bir dizi döndürür', ['find indis, filter eleman döndürür', 'find diziyi değiştirir, filter değiştirmez', 'İkisi de yalnız koşulu sağlayan ilk elemanı döndürür; aralarındaki fark yalnız çalışma hızındadır'], 'find ilk eşleşmede durur ve bulamazsa undefined verir; filter bütün diziyi tarar ve eşleşmelerin tamamını yeni bir dizide toplar.'),
  ('Python\'da any(x < 0 for x in sayilar) ifadesi bir doğrusal aramaya benzer. İlk negatif sayı bulunduğunda ne olur?', 'Değerlendirme durur ve True döner; kalan elemanlara bakılmaz', ['Bütün liste yine de sonuna kadar taranır', 'Bulunan negatif sayının indisi döner ve liste o noktadan ikiye bölünür', 'Liste sıralanır ve en küçük eleman döner'], 'any kısa devre yapar: üreteçten gelen ilk True değerinde durur. Bu, arama bulununca döngüden çıkmanın kütüphanedeki karşılığıdır.'),
  ('JavaScript\'te \'I\'.toLocaleLowerCase(\'tr\') ifadesi neden \'ı\' verir de \'I\'.toLowerCase() \'i\' verir?', 'Türkçe dil ayarı, noktasız I\'nın küçüğünü ı olarak tanımlar', ['toLowerCase yalnız sesli harfleri dönüştürür', 'toLocaleLowerCase her harfi noktasız hâle getirir', 'İkisi de aynı sonucu verir; aradaki fark yalnız işlevlerin yazım biçimindedir ve sonuç değişmez'], 'Dile bağlı olmayan dönüşüm İngilizce kuralı uygular. Türkçe aramalarda büyük-küçük harf eşitlemesi dil ayarıyla yapılmazsa \'ILIK\' ile \'ılık\' eşleşmez.'),
  ('Bir öğrenci 100 ürün arasından en ucuzunu bulmak için önce bütün ürünleri fiyata göre sıralamayı düşünüyor. Daha verimli yol hangisidir?', 'Listeyi bir kez tarayıp şimdiye dek görülen en düşük fiyatı tutmak', ['Ürünleri ikili aramayla taramak', 'Ürünleri iki kez sıralayıp ilkini almak', 'Ürünleri rastgele seçip o ana kadar en düşük fiyatlı görüneni almak ve kalanlara bakmamak'], 'En küçüğü bulmak için tek bir doğrusal tarama (n − 1 karşılaştırma) yeter; tam sıralama gereksiz yere n log n iş yapar.'),
  ('Yığın sıralaması (heapsort) kararlı bir algoritma mıdır?', 'Hayır; kök ile son elemanın takası eşit anahtarlıların sırasını bozabilir', ['Evet; her durumda eşitlerin sırasını korur', 'Evet; ama yalnız tam sayı dizilerinde', 'Hayır; çünkü yığın sıralaması yalnız azalan sırada sıralayabilir ve sonucu ters çevirmek gerekir'], 'Her adımda kökteki eleman dizinin sonuna takas edilir ve süzme sırasında elemanlar uzak konumlara taşınır; eşit anahtarlı kayıtların göreli sırası korunmaz.'),
  ('Kabarcık sıralaması adını nereden alır?', 'Büyük değerlerin her geçişte suda yükselen kabarcıklar gibi sona doğru ilerlemesinden', ['Algoritmayı ilk yazan kişinin soyadından', 'Elemanların kabarcık biçiminde bir ağaç yapısında saklanması ve her düğümün bir kabarcığa benzemesinden', 'Dizinin ortasından başlayıp iki yana doğru genişlemesinden'], 'Komşu takaslarıyla büyük bir değer, geçiş boyunca dizinin sonuna doğru \'kabarır\'. Adın algoritmanın mantığıyla doğrudan ilgisi vardır.'),
  ('Shell sıralamasının adı nereden gelir?', 'Algoritmayı 1959\'da yayımlayan Donald Shell\'in soyadından', ['Kabuk biçimindeki veri yapısından', 'Unix kabuğunda (shell) ilk kez kullanılmasından ve komut satırından çalıştırılmasından', 'Elemanların iç içe kabuklar hâlinde gruplanmasından'], 'İngilizce \'shell\' kabuk demek olsa da algoritma adını mucidi Donald L. Shell\'den alır; Türkçede \'kabuk sıralaması\' çevirisi bu yüzden yanıltıcıdır.'),
  ('Kokteyl sıralaması başka hangi adla da bilinir?', 'Çalkalayıcı (shaker) sıralaması', ['Tarak sıralaması', 'Cüce sıralaması', 'Sabır sıralaması'], 'Geçişlerin bir ileri bir geri yapılması kokteyl çalkalayıcısının hareketine benzetilmiştir; algoritma çift yönlü kabarcık sıralaması olarak da anılır.'),
  ('Donald Knuth\'un \'The Art of Computer Programming\' dizisinin sıralama ve arama algoritmalarına ayrılmış cildinin adı nedir?', 'Sorting and Searching (3. cilt)', ['Fundamental Algorithms (1. cilt)', 'Seminumerical Algorithms (2. cilt)', 'Combinatorial Algorithms (4. cilt)'], '1973\'te yayımlanan 3. cilt, sıralama ve arama yöntemlerinin ayrıntılı çözümlemesiyle bu alanın temel başvuru kaynağıdır.'),
  ('Yığın sıralaması ilk kez 1964\'te kim tarafından yayımlanmıştır?', 'J. W. J. Williams', ['Tony Hoare', 'Donald Shell', 'Edsger Dijkstra'], 'Williams, ikili yığın veri yapısını ve yığın sıralamasını 1964\'te tanıttı; aynı yıl Robert Floyd yığının aşağıdan yukarı kurulumunu iyileştirdi.'),
  ('Bir dizinin \'azalmayan\' sırada olması ile \'kesin artan\' sırada olması arasındaki fark hangisidir?', 'Azalmayanda eşit komşulara izin verilir, kesin artanda verilmez', ['Kesin artanda eşit komşulara izin verilir, azalmayanda verilmez', 'İkisi tamamen aynı anlamdadır', 'Azalmayan dizi yalnız negatif sayılardan, kesin artan dizi ise yalnız pozitif sayılardan oluşur'], '1, 2, 2, 3 azalmayandır (her i için a[i] ≤ a[i + 1]) ama kesin artan değildir (a[i] < a[i + 1] koşulu 2, 2\'de bozulur).'),
  ('Aşağıdaki sıralama algoritmalarından hangisi karşılaştırmaya dayalıdır?', 'Birleştirmeli sıralama', ['Sayma sıralaması', 'Taban sıralaması', 'Güvercin yuvası sıralaması'], 'Birleştirmeli sıralama elemanların göreli sırasını yalnız ikişerli karşılaştırmalarla belirler. Diğer üçü anahtar değerlerini doğrudan indis ya da basamak olarak kullanır.'),
  ('Hem kararlılığın hem de en kötü durumda n log n süre garantisinin gerektiği, ek belleğin sorun olmadığı bir uygulamada hangi algoritma en uygundur?', 'Birleştirmeli sıralama', ['Hızlı sıralama', 'Yığın sıralaması', 'Seçmeli sıralama'], 'Hızlı sıralama en kötü durumda karesel, yığın sıralaması kararsız, seçmeli sıralama ise karesel ve kararsızdır. Birleştirmeli sıralama iki koşulu birlikte sağlar.'),
  ('Bir sıralama işlevini sınamak için hazırlanan test girdileri arasında aşağıdakilerden hangisi en az değerli olandır?', 'Rastgele seçilmiş, birbirine çok benzeyen iki ayrı orta boy dizi', ['Boş dizi ve tek elemanlı dizi', 'Bütün elemanları birbirine eşit olan dizi', 'Ters sıralı ve zaten sıralı diziler'], 'Boş, tek elemanlı, eşit elemanlı, sıralı ve ters sıralı girdiler sınır durumlarını ve en kötü durumları yoklar. Birbirine benzeyen iki rastgele dizi yeni bir durum sınamaz.'),
  ('Python\'daki bisect.bisect işlevi hangi işlevle aynı davranır?', 'bisect_right', ['bisect_left', 'insort_left', 'index'], 'bisect, bisect_right\'ın kısa adıdır; eşit elemanlar varsa ekleme yerini onların sağında verir.'),
  ('Python\'da sorted(kayitlar, key=itemgetter(1)) ifadesindeki itemgetter(1) ne işe yarar?', 'Her kaydın 1 numaralı öğesini sıralama anahtarı olarak seçer', ['Listenin yalnız ilk kaydını döndürür', 'Kayıtları bir azaltarak sıralar', 'Listede değeri 1 olan öğeleri tamamen siler ve geriye kalan kayıtları özgün sırasıyla döndürür'], 'operator.itemgetter(1), lambda k: k[1] ile aynı işi yapan hızlı bir anahtar işlevidir; örneğin (\'ali\', 30), (\'can\', 25) yaşa göre sıralanır.'),
  ('C++\'ta std::partition ile std::stable_partition arasındaki fark nedir?', 'İkisi de koşulu sağlayanları öne alır; yalnız stable_partition grupların içindeki sırayı korur', ['partition diziyi sıralar, stable_partition yalnız böler', 'stable_partition yalnız sayılarla çalışır', 'partition koşulu sağlamayan elemanları tamamen siler, stable_partition ise onları sırasını bozmadan sona ekler'], 'partition hızlı sıralamadaki bölümleme gibi takaslarla çalışır ve sırayı bozabilir. stable_partition ek bellek kullanarak her grubun özgün sırasını korur.'),
  ('Go dilinde sort.Search(n, f) işlevi neyi döndürür?', 'f(i)\'nin doğru olduğu en küçük i\'yi', ['f\'nin doğru olduğu bütün indislerin listesini', 'n elemanlı dizinin sıralı hâlini', 'f\'nin yanlış olduğu en büyük i\'nin karesini, böylece aralığın genişliğini hesaplamayı kolaylaştırır'], 'sort.Search genel bir \'cevap üzerinde ikili arama\' aracıdır; dizi değil, monoton bir yüklem alır. Hiçbir i için doğru değilse n döner.'),
  ('Rust\'ta sıralı bir dilimde binary_search(&x) çağrısı x bulunamazsa ne döndürür?', 'Err(ekleme yeri)', ['Ok(−1)', 'None', 'Programı panik ile durdurur'], 'Sonuç Result türündedir: bulunursa Ok(indis), bulunmazsa sırayı bozmadan ekleme yapılacak konumu taşıyan Err(konum) döner. Java\'daki −(ekleme yeri) − 1 hilesine gerek kalmaz.'),
  ('Rust\'taki slice.sort() ile slice.sort_unstable() yöntemleri arasındaki temel fark nedir?', 'sort kararlıdır; sort_unstable kararsızdır ama ek bellek gerektirmez ve genellikle daha hızlıdır', ['sort artan, sort_unstable azalan sıralar', 'sort_unstable yanlış sonuç verebilir', 'sort yalnız tam sayıları, sort_unstable ise yalnız metinleri ve karakter dizilerini sıralayabilen ayrı yöntemlerdir'], 'Adlar kararlılık garantisini açıkça belirtir; eşit elemanların sırası önemli değilse sort_unstable tercih edilir.'),
  ('Go dilinde bir dilimi eşit anahtarlıların sırasını koruyarak sıralamak için hangi işlev kullanılmalıdır?', 'sort.SliceStable', ['sort.Slice', 'sort.Search', 'sort.Reverse'], 'sort.Slice kararlılık garantisi vermez. sort.SliceStable aynı karşılaştırma işlevini alır ama eşit elemanların özgün sırasını korur.'),
  ('C#\'ta Array.Sort ile LINQ\'deki OrderBy yöntemi arasındaki önemli fark hangisidir?', 'Array.Sort kararsızdır ve yerinde çalışır; OrderBy kararlıdır ve yeni bir dizi üretir', ['Array.Sort kararlıdır, OrderBy kararsızdır', 'İkisi de yalnız sayıları sıralar', 'OrderBy diziyi yerinde değiştirip sıralar, Array.Sort ise özgün diziyi koruyarak sıralı bir kopya üretir'], '.NET\'te Array.Sort içgözlemli sıralama kullanır ve eşitlerin sırasını garanti etmez. OrderBy ise kararlı sıralama yapar ve sonucu yeni bir dizide verir.'),
  ('Google\'ın V8 JavaScript motoru 2018\'de (sürüm 7.0) Array.prototype.sort için hangi algoritmaya geçmiştir?', 'Timsort', ['Kabarcık sıralaması', 'Yığın sıralaması', 'Taban sıralaması'], 'Bu geçişle V8\'deki sıralama kararlı hâle geldi; ES2019 da Array.prototype.sort\'un kararlı olmasını standartlaştırdı.'),
  ('Puanları 90, 85, 85, 70 olan yarışmacılara \'yoğun sıra\' (dense rank) verilecek: eşit puanlılar aynı sırayı alıyor ve sonraki farklı puan bir sonraki sıra numarasını alıyor. 70 puanlı yarışmacının sırası kaçtır?', '3', ['4', '2', '5'], 'Farklı puanlar 90, 85, 70 olarak sıralanır ve 1, 2, 3 numaralarını alır. \'Yarışma sırası\' kuralında ise 70 puan 4. sıraya düşerdi.'),
  ('Sıralı [1, 3, 4, 6, 9] ve [2, 3, 6, 8, 9] listeleri yan yana yürünerek \'birincide olup ikincide olmayanlar\' bulunuyor. Sonuç nedir?', '1, 4', ['2, 8', '1, 2, 4, 8', '3, 6, 9'], 'İşaretçiler küçük taraftan ilerler; birinci listedeki eleman ikincidekinden küçükse sonuca yazılır, eşitse ikisi de atlanır. 1 ve 4 ikinci listede yoktur.'),
  ('GNU sort komutu belleğe sığmayacak kadar büyük bir dosyayı sıralarken ne yapar?', 'Parçaları sıralayıp geçici dosyalara yazar, sonra bunları birleştirir', ['Dosyanın yalnız belleğe sığan kısmını sıralar, gerisini olduğu gibi bırakır', 'Hata verip işlemi durdurur', 'Dosyayı sıkıştırıp tek parça hâlinde bellekte sıralar'], 'sort, dış birleştirmeli sıralama uygular: bellek dolusu parçaları sıralı koşular olarak geçici dosyalara yazar ve sonunda çok yollu birleştirmeyle tek sıralı çıktı üretir.'),
  ('Farklı ülkelerden gelen siparişlerin zaman damgaları yerel saatle kaydedilmiş. Siparişler gerçek oluş sırasına göre dizilmek isteniyor. Sıralamadan önce ne yapılmalıdır?', 'Bütün zamanlar tek bir saat dilimine (ör. UTC) çevrilmeli', ['Zaman damgaları metin olarak sıralanmalı', 'Yalnız tarih kısmı kullanılmalı, saatler atılmalı', 'Siparişler önce ülke adına, sonra yerel saate göre sıralanmalı ve ülkeler arası fark yok sayılmalı'], 'Aynı yerel saat farklı dilimlerde farklı anlara karşılık gelir. Ortak bir saat dilimine dönüştürmeden yapılan sıralama gerçek kronolojiyi yansıtmaz.'),
  ('Bir öğrenci ikili arama hakkında dört not almış. Bu notlardan hangisi hatalıdır?', 'Tek yönlü bağlı listede de dizideki kadar hızlı çalışır', ['Dizinin arama anahtarına göre sıralı olmasını gerektirir', 'Değer bulunamazsa ekleme yerini de verebilir', 'Her adımda arama aralığını yaklaşık yarıya indirir'], 'Bağlı listede ortadaki düğüme ulaşmak için baştan yürümek gerekir; bu yüzden ikili aramanın logaritmik üstünlüğü kaybolur. Diğer üç ifade doğrudur.'),
  ('Hızlı sıralama için öne sürülen aşağıdaki savlardan hangisi doğru değildir?', 'En kötü durumda da n log n süre garanti eder', ['Pivotun seçimi performansı büyük ölçüde etkiler', 'Standart dizi gerçekleştirmesi kararlı değildir', 'Ortalama durumda n log n sürede çalışır'], 'Pivot her seferinde en küçük ya da en büyük elemana denk gelirse süre karesel olur; en kötü durum güvencesi için içgözlemli sıralama gibi önlemler gerekir.'),
  ('Bir arkadaşınız sayma sıralamasının niteliklerini sayıyor. Söylediklerinden hangisi yanlıştır?', 'Değer aralığı ne kadar geniş olursa olsun her zaman en hızlı yöntemdir', ['Elemanları birbiriyle karşılaştırmaz', 'Uygun yazılırsa kararlıdır', 'Değer aralığının boyu kadar ek bellek (sayaç dizisi) kullanır ve bu bellek girdiden bağımsız ayrılır'], 'Süre ve bellek n + k ile orantılıdır; k (değer aralığı) n\'ye göre çok büyükse sayma sıralaması karşılaştırmalı yöntemlerden çok daha kötü olur.'),
  ('Birleştirmeli sıralamanın dizi üzerindeki standart biçimi için hangi nitelendirme geçersizdir?', 'Dizilerde ek bellek kullanmadan, yerinde çalışır', ['En kötü durumda da n log n sürede biter', 'Eşitlikte soldan alındığında kararlıdır', 'Bağlı listeleri sıralamaya uygundur, çünkü yalnız liste başlarına bakarak ilerler ve rastgele erişim gerektirmez'], 'Standart dizi gerçekleştirmesi birleştirme sonucunu ayrı bir diziye yazar ve O(n) ek bellek kullanır. Yerinde türleri vardır ama çok daha karmaşıktır.'),
  ('Python\'da \'an\' in \'banana\' ifadesi True, \'an\' in [\'banana\'] ifadesi ise False verir. Farkın nedeni nedir?', 'Metinde \'in\' alt dizge arar, listede ise eşit bir eleman arar', ['Listeler \'in\' işleciyle aranamaz', 'Listede arama büyük-küçük harfe duyarlıdır', 'Metinde arama ikili, listede doğrusal yapılır ve sonuç değişir'], 'Metin için \'in\' alt dizge aramasıdır; liste için ise elemanlar tek tek \'==\' ile karşılaştırılır. Listede \'banana\' vardır ama \'an\' adlı bir eleman yoktur.'),
  ('Yalnız tam sayılardan oluşan bir dizi sıralanıyor ve kayıtlar başka hiçbir bilgi taşımıyor. Bu durumda algoritmanın kararlı olup olmaması neden önemsizdir?', 'Eşit tam sayılar birbirinden ayırt edilemez; sıralarının değişmesi sonucu etkilemez', ['Tam sayılar hiçbir zaman eşit olamaz', 'Kararsız algoritmalar tam sayıları sıralayamaz', 'Kararlılık kavramı yalnız ondalık (kayan noktalı) sayılar için tanımlıdır, tam sayılarda anlamı yoktur'], 'Kararlılık, eşit anahtarlı ama farklı ek verisi olan kayıtlarda anlam taşır. İki tane 5\'in yer değiştirmesi görülebilir bir fark yaratmaz; Java\'nın ilkel dizilerde kararsız yöntemi seçmesi de buna dayanır.'),
  ('C++\'ta std::is_sorted(v.begin(), v.end()) çağrısı ne yapar?', 'Vektörün artan sırada olup olmadığını denetleyip true ya da false döndürür', ['Vektörü sıralar ve sıralı olduğunu bildirir', 'Vektörün kaç kez sıralandığını döndürür', 'Vektörü sıralı hâle getirmek için gereken en az takas sayısını hesaplayıp döndürür'], 'is_sorted komşu elemanları karşılaştırarak doğrusal sürede yalnız denetim yapar; diziyi değiştirmez. is_sorted_until ise sıranın bozulduğu ilk konumu verir.'),
  ('Öğrenci kayıtları okul numarasına göre sıralanıyor. Bu sıralamada okul numarası alanına ne ad verilir?', 'Sıralama anahtarı', ['Pivot', 'Gözcü', 'Sayaç (frekans) değeri'], 'Kayıtların hangi alana göre karşılaştırılacağını belirleyen alana anahtar denir; kayıtların öteki alanları anahtarla birlikte taşınır.'),
  ('Bir müşteri listesinde aynı şehirdeki müşterileri yan yana toplamak isteniyor. Bunun en basit yolu hangisidir?', 'Listeyi şehir adına göre sıralamak', ['Listeyi rastgele karıştırmak', 'Listeyi müşteri numarasına göre ters çevirmek', 'Listeyi ikili aramayla taramak'], 'Sıralama eşit anahtarlı kayıtları ardışık bloklar hâlinde bir araya getirir; ardından tek bir taramayla her şehrin grubu işlenebilir.'),
  ('Python\'da t = (3, 1, 2) bir demettir (tuple). Bu demetin sıralı hâlini elde etmek için ne yapılır?', 'sorted(t) kullanılır; sonuç [1, 2, 3] listesidir', ['t.sort() çağrılır ve demet yerinde değişir', 't.reverse() çağrılır', 'Demetler hiçbir biçimde sıralanamaz; önce elemanları tek tek yeni bir demete kopyalamak gerekir'], 'Demetler değiştirilemez olduğu için sort yöntemleri yoktur. sorted her yinelenebilir nesneyi kabul eder ve sonucu yeni bir liste olarak döndürür.'),
  ('En iyi durumda (her bölümleme diziyi tam ikiye ayırıyorsa) hızlı sıralama 1024 elemanlı bir diziyi sıralarken özyineleme derinliği kaç olur?', '10', ['1024', '512', '20'], 'Her düzeyde parça boyu yarıya iner: 1024 → 512 → … → 1; bu 10 düzey eder. En kötü durumda ise derinlik eleman sayısına yaklaşır.'),
  ('İkili aramanın döngüyle (yinelemeli) yazılan biçimi ile özyinelemeli biçimi arasındaki bellek farkı nedir?', 'Döngülü biçim sabit, özyinelemeli biçim log n mertebesinde ek bellek kullanır', ['Döngülü biçim n, özyinelemeli biçim ise yalnız sabit miktarda ek bellek kullanır ve daha verimlidir', 'İkisi de dizinin bir kopyasını oluşturur', 'Özyinelemeli biçim hiç bellek kullanmaz'], 'Her özyinelemeli çağrı çağrı yığınında bir çerçeve tutar ve derinlik log n\'dir. Döngülü biçim yalnız birkaç değişkenle çalışır; bu yüzden pratikte çoğunlukla tercih edilir.'),
  ('Aşağıdan yukarı (yinelemeli) birleştirmeli sıralamanın yukarıdan aşağı (özyinelemeli) biçime göre bir avantajı hangisidir?', 'Özyineleme kullanmadığı için çağrı yığını gerektirmez', ['Ek bellek kullanmadan yerinde çalışır', 'Kararsız olduğu için daha hızlıdır', 'En kötü durumda doğrusal sürede biter, çünkü parçalar her turda ikiye katlanır'], 'Aşağıdan yukarı biçim 1, 2, 4, … boyutlu komşu parçaları döngülerle birleştirir. Birleştirme için ek dizi yine gerekir, ama özyineleme yükü ortadan kalkar.'),
  ('Bir klasörde \'rapor*.pdf\' kalıbıyla arama yapılıyor (\'*\' sıfır ya da daha çok karakter yerine geçer). Hangi dosya bu kalıpla eşleşmez?', 'eski_rapor.pdf', ['rapor.pdf', 'rapor2024.pdf', 'rapor_son.pdf'], 'Kalıp \'rapor\' ile başlayıp \'.pdf\' ile biten adları kapsar; \'*\' boş da olabileceğinden \'rapor.pdf\' de eşleşir. \'eski_rapor.pdf\' ise \'rapor\' ile başlamaz.'),
  ('Unix\'te \'grep −v hata kayit.log\' komutu ne yapar?', '\'hata\' içermeyen satırları yazdırır', ['\'hata\' içeren satırların sayısını yazdırır', '\'hata\' sözcüğünü dosyadan siler', 'Dosyanın yalnız ilk \'hata\' satırını gösterir'], '−v (invert) seçeneği eşleşmeyi tersine çevirir; böylece kalıbı içermeyen satırlar süzülerek gösterilir.'),
  ('Bir metin düzenleyicide \'kar\' aranırken \'karpuz\' ve \'kartal\' sözcüklerinin sonuç olarak gelmemesi isteniyor. Hangi arama seçeneği açılmalıdır?', 'Yalnız tam sözcükleri eşleştir', ['Büyük-küçük harfe duyarlı ol', 'Düzenli ifade kullan', 'Yukarı doğru ara'], 'Tam sözcük seçeneği, eşleşmenin önünde ve arkasında harf olmamasını (sözcük sınırı) ister. Harf duyarlılığı ise yalnız büyük-küçük harf farkını denetler.'),
  ('C standart kütüphanesindeki strstr(metin, kalip) işlevi kalıp metinde bulunmazsa ne döndürür?', 'NULL işaretçisi', ['−1', '0 konumunu gösteren bir işaretçi', 'Metnin son karakterini gösteren bir işaretçi'], 'strstr, kalıbın metindeki ilk geçişinin başlangıcını gösteren bir işaretçi döndürür; eşleşme yoksa NULL verir. Konum indisi gerekiyorsa dönen işaretçiden metnin başı çıkarılır.'),
  ('Python\'da sorted(\'elma armut kiraz\'.split()) ifadesinin sonucu nedir?', '[\'armut\', \'elma\', \'kiraz\']', ['[\'elma\', \'armut\', \'kiraz\']', '\'armut elma kiraz\'', '[\'a\', \'a\', \'e\', \'i\', \'k\', \'l\', \'m\', \'r\', \'r\', \'t\', \'u\', \'z\']'], 'split metni sözcük listesine böler; sorted bu listeyi alfabetik sıraya dizip yeni bir liste döndürür. Sonuç metin değil listedir.'),
  ('Sırasız 1 milyon elemanlı bir dizide doğrusal arama 4 işlemci çekirdeğine bölünüyor; her çekirdek dizinin dörtte birini tarıyor. En kötü durumda süre yaklaşık nasıl değişir?', 'Yaklaşık dörtte birine iner', ['Değişmez', 'Yarıya iner', 'log₄ n mertebesine iner, çünkü her çekirdek ikili arama yapar'], 'Her çekirdek 250 000 elemana bakar ve parçalar aynı anda taranır. Bulunan sonucu öteki çekirdeklere bildirip onları durdurmak ek bir koordinasyon gerektirir.'),
  ('Kova sıralamasında her kova kendi içinde sıralandıktan sonra sonuç dizisi nasıl elde edilir?', 'Kovalar numara sırasıyla uç uca eklenir', ['Kovalar yeniden karıştırılıp tek kovaya dökülür', 'Her kovadan yalnız en küçük eleman alınır', 'Kovalar ters sırayla, en büyük numaralıdan başlanarak birleştirilir'], 'Kovalar değer aralıklarına göre sıralı olduğundan, düşük numaralı kovanın bütün elemanları sonrakilerden küçüktür; uç uca eklemek yeterlidir.'),
  ('n elemanlı bir dizide kabarcık sıralamasının tek bir geçişinde en fazla kaç takas yapılabilir?', 'n − 1', ['n', '1', 'n(n − 1)/2'], 'Bir geçişte n − 1 komşu çift karşılaştırılır ve her biri en fazla bir takasa yol açar. En büyük eleman baştaysa ilk geçişte bu sayıya ulaşılır.'),
  ('Eklemeli sıralamanın dış döngüsü neden dizinin ilk elemanından değil ikinci elemanından başlar?', 'Tek elemanlı baş kısım zaten sıralı sayılır', ['İlk eleman her zaman en küçük elemandır', 'İlk eleman gözcü olarak ayrılmıştır ve sıralanmaz', 'Dizinin ilk elemanına doğrudan erişilemez'], 'Algoritma her adımda bir elemanı solundaki sıralı bölüme yerleştirir; başlangıçta bu bölüm yalnız ilk elemandan oluşur ve kendiliğinden sıralıdır.'),
  ('Bir ligde sıralama önce puana, eşitlikte averaja göre yapılıyor. A: 10 puan, +3 averaj; B: 10 puan, +5 averaj; C: 12 puan, −1 averaj. Sıralama nedir?', 'C, B, A', ['B, A, C', 'C, A, B', 'B, C, A'], 'Önce puana bakılır ve 12 puanlı C birinci olur. A ile B\'nin puanı eşittir; ikinci ölçüt olan averajda B (+5) A\'yı (+3) geçer.'),
  ('Sabır sıralaması (patience sort) adını nereden alır?', 'Tek kişilik bir iskambil oyunundaki kart yığınlarından', ['Algoritmanın çok yavaş olmasından', 'Algoritmayı ilk yayımlayan bilgisayar bilimcinin soyadından', 'Bir yazılım şirketinin ürününden'], 'Algoritma, \'patience\' adı verilen tek kişilik kart oyunlarındaki gibi kartları kurallara göre yığınlara dağıtır.'),
  ('Rastgele karıştırmaya dayanan bogo sıralamasının en kötü durumda kaç adımda biteceği hakkında ne söylenebilir?', 'Bir üst sınır yoktur; şanssızlıkla sonsuza dek sürebilir', ['En fazla n! adımda biter', 'En fazla n² adımda biter', 'Her zaman tam n adımda biter, çünkü her karıştırma bir elemanı yerine koyar'], 'Her karıştırma bağımsızdır ve sıralı dizilişin çıkması garanti edilmez; beklenen süre sonludur ama en kötü durum sınırsızdır.'),
  ('Yığın sıralamasının iki ana aşamasından ilki hangisidir?', 'Diziden bir max-yığın kurmak', ['Diziyi ikiye bölmek', 'Pivot seçmek', 'Elemanları değerlerine göre kovalara dağıtmak'], 'Önce dizi yığın özelliğini sağlayacak biçimde düzenlenir; ikinci aşamada kök tekrar tekrar sona alınıp yığın küçültülür.'),
  ('Taban sıralamasının adındaki \'taban\' neyi ifade eder?', 'Sayıların yazıldığı sayı sisteminin tabanını, yani bir basamağın alabileceği değer sayısını', ['Dizinin en küçük elemanını', 'Sıralamanın yapıldığı veritabanını', 'Dizinin bellekte başladığı temel (taban) adresi, yani ilk elemanın konumunu'], 'Onluk tabanda her basamak 10 değer alır ve her geçişte 10 kova kullanılır; ikilik tabanda 2, bayt tabanında 256 kova kullanılır.'),
];
